"use client";

import { useEffect, useRef, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { BookmarkPlus, Loader2, Paperclip, Plus, Sparkles, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { useSupport } from "./provider";
import type { Address, ApprovedAnswer, FileInfo, TicketDetail } from "./client";
import { contactLabel, fillPlaceholders, formatBytes } from "./format";
import { AnswerPicker, ApprovedAnswerDialog, answerOptionId, matchAnswers } from "./memory";
import { DraftBar, RefineRow, foreignLanguage, type RefineAction } from "./ai";
import { ProposedActions, undecidedActions } from "./actions";
import { HeldReply, useAutopilotReason } from "./autopilot";
import { VoiceButton, VoicePanel, useVoice, useVoiceEngine, type VoiceIntent } from "./voice";

type Mode = "reply" | "note";

export function SupportComposer({ detail }: { detail: TicketDetail }) {
  const { client, t, locale, viewerId } = useSupport();
  const queryClient = useQueryClient();
  const ticketId = detail.ticket.id;
  const blocked = detail.replyBlockedReason;
  const [mode, setMode] = useState<Mode>(blocked ? "note" : "reply");
  const [text, setText] = useState("");
  const [files, setFiles] = useState<FileInfo[]>([]);
  const [uploading, setUploading] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const fileInput = useRef<HTMLInputElement>(null);

  const limits = detail.channel?.capabilities;
  const maxLength = mode === "reply" ? limits?.maxTextLength ?? null : null;
  const attachmentsAllowed = mode === "note" || Boolean(limits?.attachments);
  const to = detail.recipients.to;
  const recipient = to ? to.name || to.address : contactLabel(detail.contact);
  const isEmail = detail.channel?.kind === "email";
  // null until the agent changes who's copied; the server's default applies until then.
  const [ccEdit, setCcEdit] = useState<Address[] | null>(null);
  const cc = ccEdit ?? detail.recipients.cc;
  const [ccDraft, setCcDraft] = useState<string | null>(null);

  const addCc = () => {
    const value = (ccDraft ?? "").trim();
    if (!value) return setCcDraft(null);
    if (!EMAIL.test(value)) return setError(t("composer.invalidCc", { address: value }));
    setError(null);
    const known = value.toLowerCase();
    if (!cc.some((a) => a.address.toLowerCase() === known) && known !== to?.address.toLowerCase()) setCcEdit([...cc, { address: value }]);
    setCcDraft(null);
  };

  // AI, when the client has it: the suggested reply, rewrites of what's in the box, and Undo.
  const ai = client.ai;
  const suggestion = ai && !blocked ? detail.suggestion ?? null : null;
  const [discarded, setDiscarded] = useState<string | null>(null);
  // A reply Autopilot is holding isn't offered for the box: it goes out by itself unless the agent stops it.
  const held = suggestion?.kind === "draft" && suggestion.autopilot === "held" ? suggestion : null;
  const draft = suggestion?.kind === "draft" && suggestion.text && suggestion.id !== discarded && !held ? suggestion : null;
  const leftToAgent = useAutopilotReason(draft);
  /** The suggestion the text in the box started from. */
  const [draftId, setDraftId] = useState<string | null>(null);
  const [history, setHistory] = useState<string[]>([]);
  const [busy, setBusy] = useState<string | null>(null);
  const offered = useRef<string | null>(null);
  const applied = Boolean(draft && draftId === draft.id && text.trim());
  // What the suggested reply assumes was done and nobody has approved or skipped yet.
  const undecided = applied && ai?.runAction ? undecidedActions(draft?.actions) : [];
  /** Set when the agent pressed Send with those still open: how they wanted it sent. */
  const [confirming, setConfirming] = useState<{ status: "waiting" | "solved" } | null>(null);
  const lastMessage = detail.timeline.filter((e) => e.type === "message" && e.message.kind !== "note" && !e.message.auto).at(-1);
  const canSuggest = Boolean(ai && !blocked && !suggestion && lastMessage?.type === "message" && lastMessage.message.kind === "inbound");

  const applyDraft = () => {
    if (!draft) return;
    if (text.trim()) setHistory((h) => [...h, text]);
    setText(draft.text ?? "");
    setDraftId(draft.id);
    setMode("reply");
  };
  // A suggestion fills an empty reply box once. Text the agent already wrote is never replaced.
  useEffect(() => {
    if (!draft || offered.current === draft.id) return;
    offered.current = draft.id;
    if (!text.trim() && mode === "reply") {
      setText(draft.text ?? "");
      setDraftId(draft.id);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draft?.id]);

  const discardDraft = () => {
    if (!draft || !ai) return;
    if (applied) {
      setHistory((h) => [...h, text]);
      setText("");
    }
    setDiscarded(draft.id);
    setDraftId(null);
    ai.discardSuggestion({ id: draft.id })
      .catch(() => setDiscarded(null))
      .finally(() => {
        queryClient.invalidateQueries({ queryKey: ["support", "ticket", ticketId] });
        queryClient.invalidateQueries({ queryKey: ["support", "tickets"] });
      });
  };

  const runAi = async (action: RefineAction | "suggest") => {
    if (!ai || busy) return;
    setBusy(typeof action === "string" ? action : "custom");
    setError(null);
    try {
      if (action === "suggest") {
        await ai.draft({ ticketId });
        await queryClient.invalidateQueries({ queryKey: ["support", "ticket", ticketId] });
        return;
      }
      const before = text;
      const result =
        action === "writeUp"
          ? await ai.writeUp({ ticketId, notes: before })
          : await ai.refine({ ticketId, text: before, instruction: action, ...(action === "translate" && translateTo ? { language: translateTo } : {}) });
      setHistory((h) => [...h, before]);
      setText(result.text);
    } catch (e) {
      setError(e instanceof Error && e.message ? e.message : t("ai.failed"));
    } finally {
      setBusy(null);
    }
  };
  const translateTo = foreignLanguage(detail, locale);
  const undo = () => {
    setText(history.at(-1) ?? "");
    setHistory((h) => h.slice(0, -1));
  };

  // Approved answers, when the client lists them: "/" at the start of a line opens the list, and the
  // chosen answer goes in with this customer's name in place of {name}. No model is involved.
  const answers = useQuery({
    queryKey: ["support", "ai", "answers"],
    queryFn: () => ai!.listApprovedAnswers!(),
    enabled: Boolean(ai?.listApprovedAnswers),
    staleTime: 60_000,
  }).data;
  const hasAnswers = Boolean(answers?.length);
  const agents = useQuery({ queryKey: ["support", "agents"], queryFn: () => client.listAgents(), staleTime: 5 * 60_000, enabled: hasAnswers });
  const [slash, setSlash] = useState<{ start: number; end: number; query: string } | null>(null);
  const [activeAnswer, setActiveAnswer] = useState(0);
  /** Where the agent closed the list with Escape, so it stays closed while they finish that line. */
  const closedSlash = useRef<number | null>(null);
  const trackSlash = (value: string, at: number | null) => {
    const found = hasAnswers && mode === "reply" && at !== null ? /(^|\n)\/([^\n]*)$/.exec(value.slice(0, at)) : null;
    const start = found ? found.index + found[1]!.length : null;
    if (start === null) closedSlash.current = null;
    const next = found && start !== closedSlash.current ? { start: start!, end: at!, query: found[2]! } : null;
    if (next?.query !== slash?.query) setActiveAnswer(0);
    setSlash(next);
  };
  const matches = slash ? matchAnswers(answers ?? [], slash.query, detail.insight?.language ?? null) : [];
  // A line that starts with "/" and goes on without matching anything is just a line.
  const picking = slash !== null && (matches.length > 0 || slash.query.length <= 30);
  const firstName = (name: string | null | undefined) => name?.trim().split(/\s+/)[0] ?? null;
  const chooseAnswer = (answer: ApprovedAnswer) => {
    if (!slash) return;
    const filled = fillPlaceholders(answer.text, {
      name: firstName(detail.contact.name),
      company: detail.customer?.name,
      agent: firstName(agents.data?.find((a) => a.id === viewerId)?.name),
    });
    const around = `${text.slice(0, slash.start)}${text.slice(slash.end)}`;
    setText(`${text.slice(0, slash.start)}${filled}${text.slice(slash.end)}`);
    // An answer put into an empty box replaces the suggestion: the reply no longer starts from it.
    if (!around.trim()) setDraftId(null);
    caret.current = slash.start + filled.length;
    setSlash(null);
  };
  /** The reply to save as an approved answer, while its dialog is open. */
  const [answerFrom, setAnswerFrom] = useState<string | null>(null);

  // Voice, when there's a way to listen. An empty reply box takes what's said as notes to write up;
  // one with text takes it as a change to make. Either way the agent can have their words inserted as spoken.
  const { engine, shortcut } = useVoiceEngine();
  const caret = useRef<number | null>(null);
  const [plainVoice, setPlainVoice] = useState(false);
  useEffect(() => {
    try {
      setPlainVoice(localStorage.getItem(PLAIN_VOICE) === "1");
    } catch {
      // No storage: the choice lasts for this ticket.
    }
  }, []);
  const smartIntent: VoiceIntent | null = mode !== "reply" ? null : text.trim() ? "instruction" : "writeUp";
  const voiceIntents: VoiceIntent[] = smartIntent ? [smartIntent, "insert"] : ["insert"];
  const voiceIntent: VoiceIntent = smartIntent && !plainVoice ? smartIntent : "insert";
  const chooseVoiceIntent = (intent: VoiceIntent) => {
    setPlainVoice(intent === "insert");
    try {
      localStorage.setItem(PLAIN_VOICE, intent === "insert" ? "1" : "0");
    } catch {
      // See above.
    }
  };
  const voice = useVoice({
    engine: ai ? engine : null,
    async resolve(said) {
      const before = text;
      if (voiceIntent === "insert") {
        const at = Math.min(caret.current ?? before.length, before.length);
        const head = before.slice(0, at);
        const tail = before.slice(at);
        const inserted = `${head}${head && !/\s$/.test(head) ? " " : ""}${said}`;
        return () => {
          if (before.trim()) setHistory((h) => [...h, before]);
          setText(`${inserted}${tail && !/^\s/.test(tail) ? " " : ""}${tail}`);
          caret.current = inserted.length;
        };
      }
      const result =
        voiceIntent === "writeUp"
          ? await ai!.writeUp({ ticketId, notes: said })
          : await ai!.refine({ ticketId, text: before, instruction: { custom: said } });
      return () => {
        setHistory((h) => [...h, before]);
        setText(result.text);
      };
    },
  });
  const voiceOn = voice.phase !== "idle";
  const canSpeak = Boolean(ai && engine) && !(mode === "reply" && blocked);
  const voiceKeys = useRef<(event: KeyboardEvent) => void>(() => {});
  useEffect(() => {
    voiceKeys.current = (event) => {
      if (event.key === "Escape" && voiceOn) {
        event.preventDefault();
        voice.cancel();
      } else if (event.code === "Space" && event.shiftKey && (event.metaKey || event.ctrlKey) && !event.repeat) {
        event.preventDefault();
        if (voice.phase === "listening") voice.stop();
        else if (busy === null && !send.isPending) voice.start();
      }
    };
  });
  useEffect(() => {
    if (!canSpeak) return;
    const onKey = (event: KeyboardEvent) => voiceKeys.current(event);
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [canSpeak]);

  const send = useMutation({
    mutationFn: (status: "waiting" | "solved" | null) => {
      const attachmentIds = files.map((f) => f.id);
      return mode === "note"
        ? client.addNote({ ticketId, text, attachmentIds })
        : client.reply({
            ticketId,
            text,
            attachmentIds,
            status: status ?? "waiting",
            ...(ccEdit ? { cc: ccEdit } : {}),
            ...(applied && draft ? { suggestionId: draft.id } : {}),
          });
    },
    onSuccess: () => {
      setText("");
      setFiles([]);
      setError(null);
      setCcEdit(null);
      setDraftId(null);
      setHistory([]);
      setSlash(null);
      setConfirming(null);
    },
    onError: (e) => setError(e instanceof Error && e.message ? e.message : t("errors.send")),
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["support", "ticket", ticketId] });
      queryClient.invalidateQueries({ queryKey: ["support", "tickets"] });
      queryClient.invalidateQueries({ queryKey: ["support", "counts"] });
    },
  });

  const upload = async (list: FileList | null) => {
    if (!list?.length) return;
    setError(null);
    for (const file of Array.from(list)) {
      setUploading((n) => n + 1);
      try {
        const saved = await client.upload({ ticketId, file });
        setFiles((current) => [...current, saved]);
      } catch (e) {
        setError(e instanceof Error && e.message ? e.message : t("errors.upload"));
      } finally {
        setUploading((n) => n - 1);
      }
    }
    if (fileInput.current) fileInput.current.value = "";
  };

  /** Sends, unless the reply says something was done that nobody approved: then it asks first. */
  const trySend = (status: "waiting" | "solved" | null) => {
    if (mode === "reply" && undecided.length) return setConfirming({ status: status ?? "waiting" });
    send.mutate(status);
  };
  const tooLong = maxLength !== null && text.length > maxLength;
  const canSend = text.trim().length > 0 && !tooLong && uploading === 0 && !send.isPending && busy === null && !voiceOn && (mode === "note" || !blocked);

  return (
    <div className={cn("rounded-xl border bg-card", mode === "note" && "border-amber-300/60 dark:border-amber-500/30")}>
      <div className="flex items-center gap-1 border-b px-2 pt-1" role="tablist">
        {(["reply", "note"] as const).map((m) => (
          <button
            key={m}
            type="button"
            role="tab"
            aria-selected={mode === m}
            disabled={voiceOn}
            onClick={() => setMode(m)}
            className={cn(
              "-mb-px border-b-2 px-3 py-2 text-sm font-medium transition-colors",
              mode === m
                ? m === "note"
                  ? "border-amber-500 text-amber-700 dark:text-amber-300"
                  : "border-primary text-primary"
                : "border-transparent text-muted-foreground hover:text-foreground"
            )}
          >
            {t(m === "reply" ? "composer.reply" : "composer.note")}
          </button>
        ))}
      </div>

      {mode === "reply" && blocked ? (
        <p className="px-4 py-5 text-sm text-muted-foreground">{t(`composer.blocked.${blocked}`)}</p>
      ) : (
        <>
          {mode === "reply" && (
            <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5 px-4 pt-3 text-xs text-muted-foreground">
              <span>
                {t("composer.to")} <bdi className="text-foreground">{recipient}</bdi>
              </span>
              {isEmail && (
                <span className="flex flex-wrap items-center gap-1.5">
                  {(cc.length > 0 || ccDraft !== null) && <span>{t("composer.cc")}</span>}
                  {cc.map((a) => (
                    <span key={a.address} className="inline-flex items-center gap-1 rounded-md border bg-background px-1.5 py-0.5 text-foreground">
                      <bdi title={a.address}>{a.name || a.address}</bdi>
                      <button
                        type="button"
                        onClick={() => setCcEdit(cc.filter((c) => c.address !== a.address))}
                        className="text-muted-foreground hover:text-foreground"
                        aria-label={t("composer.removeCc", { name: a.name || a.address })}
                      >
                        <X className="size-3" />
                      </button>
                    </span>
                  ))}
                  {ccDraft !== null ? (
                    <input
                      autoFocus
                      type="email"
                      dir="ltr"
                      value={ccDraft}
                      onChange={(e) => setCcDraft(e.target.value)}
                      onBlur={addCc}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" || e.key === "," || e.key === " ") {
                          e.preventDefault();
                          addCc();
                        } else if (e.key === "Escape") {
                          setCcDraft(null);
                        }
                      }}
                      placeholder={t("composer.ccPlaceholder")}
                      aria-label={t("composer.addCc")}
                      className="h-6 w-48 rounded-md border bg-background px-1.5 text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
                    />
                  ) : (
                    <button
                      type="button"
                      onClick={() => setCcDraft("")}
                      className="inline-flex items-center gap-0.5 hover:text-foreground"
                    >
                      <Plus className="size-3" />
                      {cc.length ? <span className="sr-only">{t("composer.addCc")}</span> : t("composer.cc")}
                    </button>
                  )}
                </span>
              )}
            </div>
          )}
          {mode === "reply" && held && <HeldReply ticketId={ticketId} suggestion={held} />}
          {mode === "reply" && draft && <DraftBar suggestion={draft} applied={applied} onUse={applyDraft} onDiscard={discardDraft} />}
          {mode === "reply" && draft && leftToAgent && <p className="px-4 pt-1.5 text-xs text-muted-foreground">{leftToAgent}</p>}
          {mode === "reply" && draft?.actions && (
            <ProposedActions
              ticketId={ticketId}
              suggestionId={draft.id}
              actions={draft.actions}
              text={applied ? text : null}
              onText={(next) => {
                setHistory((h) => [...h, text]);
                setText(next);
              }}
            />
          )}
          {mode === "reply" && suggestion?.kind === "cannot_answer" && !text.trim() && (
            <p dir="auto" className="px-4 pt-3 text-xs text-muted-foreground">
              {t("ai.noDraft", { reason: suggestion.reason ?? "" })}
            </p>
          )}
          <div className="relative">
            {picking && <AnswerPicker answers={matches} active={activeAnswer} onActive={setActiveAnswer} onChoose={chooseAnswer} />}
            <Textarea
              value={text}
              dir="auto"
              readOnly={(busy !== null && busy !== "suggest") || voiceOn}
              onChange={(e) => {
                setText(e.target.value);
                trackSlash(e.target.value, e.target.selectionStart);
              }}
              onSelect={(e) => {
                caret.current = e.currentTarget.selectionStart;
                trackSlash(e.currentTarget.value, e.currentTarget.selectionStart);
              }}
              onBlur={() => setSlash(null)}
              onKeyDown={(e) => {
                if (picking && e.key === "Escape") {
                  e.preventDefault();
                  closedSlash.current = slash.start;
                  setSlash(null);
                } else if (picking && matches.length && (e.key === "ArrowDown" || e.key === "ArrowUp")) {
                  e.preventDefault();
                  setActiveAnswer((i) => (i + (e.key === "ArrowDown" ? 1 : matches.length - 1)) % matches.length);
                } else if (picking && matches.length && (e.key === "Enter" || e.key === "Tab") && !e.metaKey && !e.ctrlKey && !e.shiftKey) {
                  e.preventDefault();
                  chooseAnswer(matches[activeAnswer] ?? matches[0]!);
                } else if (e.key === "Enter" && (e.metaKey || e.ctrlKey) && canSend) {
                  e.preventDefault();
                  trySend(null);
                }
              }}
              placeholder={t(mode === "reply" ? (hasAnswers ? "composer.replyPlaceholderAnswers" : "composer.replyPlaceholder") : "composer.notePlaceholder")}
              className="min-h-28 resize-y border-0 bg-transparent px-4 shadow-none focus-visible:ring-0 dark:bg-transparent"
              aria-label={t(mode === "reply" ? "composer.reply" : "composer.note")}
              aria-controls={picking ? "support-answers" : undefined}
              aria-activedescendant={picking && matches[activeAnswer] ? answerOptionId(matches[activeAnswer]!.id) : undefined}
            />
          </div>
          {files.length > 0 && (
            <ul className="flex flex-wrap gap-2 px-4 pb-2">
              {files.map((file) => (
                <li key={file.id} className="inline-flex items-center gap-1.5 rounded-md border bg-background px-2 py-1 text-xs">
                  <bdi className="max-w-48 truncate">{file.filename}</bdi>
                  <span className="text-muted-foreground tabular-nums">{formatBytes(file.size, locale)}</span>
                  <button
                    type="button"
                    onClick={() => setFiles((current) => current.filter((f) => f.id !== file.id))}
                    className="text-muted-foreground hover:text-foreground"
                    aria-label={t("composer.removeFile", { name: file.filename })}
                  >
                    <X className="size-3.5" />
                  </button>
                </li>
              ))}
            </ul>
          )}
          {error && <p className="px-4 pb-2 text-sm text-destructive">{error}</p>}
          {confirming && undecided.length > 0 && (
            <div role="alert" className="mx-4 mb-2 flex flex-wrap items-center justify-between gap-x-4 gap-y-2 rounded-lg border border-amber-300/60 bg-amber-50 px-3 py-2 text-sm dark:border-amber-500/30 dark:bg-amber-500/10">
              <p className="min-w-0 flex-1 basis-64">{t("ai.actions.unapproved", { titles: undecided.map((a) => a.title).join(", ") })}</p>
              <span className="flex shrink-0 items-center gap-1.5">
                <Button type="button" size="sm" variant="ghost" className="h-7" onClick={() => setConfirming(null)}>
                  {t("ai.actions.review")}
                </Button>
                <Button type="button" size="sm" variant="outline" className="h-7" disabled={!canSend} onClick={() => send.mutate(confirming.status)}>
                  {send.isPending && <Loader2 className="size-3.5 animate-spin" />}
                  {t("ai.actions.sendAnyway")}
                </Button>
              </span>
            </div>
          )}
          {canSpeak && <VoicePanel voice={voice} intent={voiceIntent} intents={voiceIntents} onIntent={chooseVoiceIntent} />}
          {ai && mode === "reply" && !voiceOn && (text.trim() || history.length > 0) && (
            <RefineRow
              busy={busy}
              onRun={runAi}
              onUndo={history.length ? undo : null}
              // A suggestion is already in the customer's language until the agent rewrites it.
              translateTo={draft && text === draft.text ? null : translateTo}
              showWriteUp={!applied && history.length === 0}
            />
          )}
          <div className="flex flex-wrap items-center justify-between gap-2 border-t px-3 py-2">
            <div className="flex items-center gap-3">
              {attachmentsAllowed && (
                <>
                  <input ref={fileInput} type="file" multiple hidden onChange={(e) => upload(e.target.files)} />
                  <Button type="button" variant="ghost" size="sm" onClick={() => fileInput.current?.click()} disabled={uploading > 0}>
                    {uploading ? <Loader2 className="size-4 animate-spin" /> : <Paperclip className="size-4" />}
                    {t("composer.attach")}
                  </Button>
                </>
              )}
              {canSpeak && busy === null && <VoiceButton voice={voice} shortcut={shortcut} />}
              {mode === "reply" && ai?.saveApprovedAnswer && text.trim() && !picking && !voiceOn && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-8"
                  title={t("ai.answers.saveReply")}
                  aria-label={t("ai.answers.saveReply")}
                  disabled={busy !== null}
                  onClick={() => setAnswerFrom(text)}
                >
                  <BookmarkPlus className="size-4" />
                </Button>
              )}
              {mode === "reply" && canSuggest && !text.trim() && !voiceOn && (
                <Button type="button" variant="ghost" size="sm" onClick={() => runAi("suggest")} disabled={busy !== null}>
                  {busy === "suggest" ? <Loader2 className="size-4 animate-spin" /> : <Sparkles className="size-4" />}
                  {t("ai.suggest")}
                </Button>
              )}
              {maxLength !== null && (
                <span className={cn("text-xs tabular-nums", tooLong ? "text-destructive" : "text-muted-foreground")}>
                  {text.length}/{maxLength}
                </span>
              )}
            </div>
            <div className="flex items-center gap-2">
              {mode === "reply" ? (
                <>
                  <Button type="button" variant="outline" size="sm" disabled={!canSend} onClick={() => trySend("solved")}>
                    {t("composer.sendAndSolve")}
                  </Button>
                  <Button type="button" size="sm" disabled={!canSend} onClick={() => trySend("waiting")}>
                    {send.isPending && <Loader2 className="size-4 animate-spin" />}
                    {t("composer.send")}
                  </Button>
                </>
              ) : (
                <Button type="button" size="sm" disabled={!canSend} onClick={() => send.mutate(null)}>
                  {send.isPending && <Loader2 className="size-4 animate-spin" />}
                  {t("composer.addNote")}
                </Button>
              )}
            </div>
          </div>
        </>
      )}
      <ApprovedAnswerDialog
        open={answerFrom !== null}
        onOpenChange={(open) => !open && setAnswerFrom(null)}
        from={answerFrom !== null ? { ticketId, text: answerFrom } : undefined}
      />
    </div>
  );
}

const PLAIN_VOICE = "tendkit:voice:plain";
const EMAIL = /^[^\s@<>,;]+@[^\s@<>,;]+\.[^\s@<>,;]+$/;

"use client";

import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ArrowUp, Loader2, Sparkles, Undo2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuRadioGroup, DropdownMenuRadioItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { useSupport } from "./provider";
import type { RefineInstruction, Suggestion, TicketDetail, Urgency } from "./client";

/*
 * The AI parts of the screens. Each one renders only when the client has `ai`, so apps without
 * it never see them.
 */

const URGENCIES: Urgency[] = ["urgent", "high", "normal", "low"];

const urgencyStyles: Record<Urgency, string> = {
  urgent: "bg-red-50 text-red-700 ring-red-600/20 dark:bg-red-500/10 dark:text-red-300",
  high: "bg-amber-50 text-amber-800 ring-amber-600/20 dark:bg-amber-500/10 dark:text-amber-300",
  normal: "",
  low: "",
};

/** "Urgent" or "High" on an inbox row. Ordinary tickets carry no mark. */
export function UrgencyMark({ urgency }: { urgency: Urgency | null | undefined }) {
  const { t } = useSupport();
  if (urgency !== "urgent" && urgency !== "high") return null;
  return (
    <span className={cn("inline-flex shrink-0 items-center rounded-md px-1.5 py-0.5 text-[11px] font-medium ring-1 ring-inset", urgencyStyles[urgency])}>
      {t(`ai.urgency.${urgency}`)}
    </span>
  );
}

/** "es" → "Spanish", in the agent's language. */
export function languageName(code: string, locale: string) {
  try {
    return new Intl.DisplayNames([locale], { type: "language" }).of(code) ?? code;
  } catch {
    return code;
  }
}

const baseLanguage = (code: string) => code.toLowerCase().split("-")[0];

/** The customer's language when it isn't the agent's: what "Translate" works from and to. */
export function foreignLanguage(detail: TicketDetail, locale: string) {
  const language = detail.insight?.language ?? null;
  return language && baseLanguage(language) !== baseLanguage(locale) ? language : null;
}

/** Under the ticket's subject: what the customer needs, with the urgency and topic an agent can correct. */
export function TicketInsightBar({ detail }: { detail: TicketDetail }) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const insight = detail.insight ?? null;
  const ticketId = detail.ticket.id;
  const [open, setOpen] = useState<"urgency" | "topic" | null>(null);
  const settings = useQuery({
    queryKey: ["support", "ai", "settings"],
    queryFn: () => ai!.getSettings(),
    enabled: Boolean(ai && insight),
    staleTime: 5 * 60_000,
  });
  const change = useMutation({
    mutationFn: (input: { topic?: string; urgency?: Urgency }) => ai!.setInsight({ ticketId, ...input }),
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["support", "ticket", ticketId] });
      queryClient.invalidateQueries({ queryKey: ["support", "tickets"] });
    },
  });
  if (!ai || !insight) return null;

  const urgency = insight.urgency ?? "normal";
  const topic = insight.topic ?? "other";
  const topicLabel = (value: string) => (value === "other" ? t("ai.otherTopic") : value);
  const topics = [...new Set([...(settings.data?.topics ?? []), topic, "other"])];
  const chip = "inline-flex items-center gap-1 rounded-md border bg-background px-2 py-1 text-xs transition-colors hover:bg-muted/60 disabled:opacity-60";

  return (
    <div className="mt-2 space-y-2">
      {insight.summary && (
        <p dir="auto" className="text-sm text-muted-foreground">
          {insight.summary}
        </p>
      )}
      <div className="flex flex-wrap items-center gap-2">
        <DropdownMenu open={open === "urgency"} onOpenChange={(next) => setOpen(next ? "urgency" : null)}>
          <DropdownMenuTrigger
            className={cn(chip, (urgency === "urgent" || urgency === "high") && cn("border-transparent ring-1 ring-inset", urgencyStyles[urgency]))}
            disabled={change.isPending}
            title={insight.urgencyReason ?? undefined}
          >
            <span className="opacity-70">{t("ai.urgencyLabel")}</span>
            <span className="font-medium">{t(`ai.urgency.${urgency}`)}</span>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" className="w-auto min-w-36">
            <DropdownMenuRadioGroup
              value={urgency}
              onValueChange={(value) => {
                setOpen(null);
                if (value !== urgency) change.mutate({ urgency: value as Urgency });
              }}
            >
              {URGENCIES.map((value) => (
                <DropdownMenuRadioItem key={value} value={value}>
                  {t(`ai.urgency.${value}`)}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>

        <DropdownMenu open={open === "topic"} onOpenChange={(next) => setOpen(next ? "topic" : null)}>
          <DropdownMenuTrigger className={chip} disabled={change.isPending}>
            <span className="text-muted-foreground">{t("ai.topicLabel")}</span>
            <span className="font-medium">{topicLabel(topic)}</span>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" className="max-h-80 w-auto min-w-36 overflow-y-auto">
            <DropdownMenuRadioGroup
              value={topic}
              onValueChange={(value) => {
                setOpen(null);
                if (value !== topic) change.mutate({ topic: String(value) });
              }}
            >
              {topics.map((value) => (
                <DropdownMenuRadioItem key={value} value={value}>
                  {topicLabel(value)}
                </DropdownMenuRadioItem>
              ))}
            </DropdownMenuRadioGroup>
          </DropdownMenuContent>
        </DropdownMenu>

        {insight.mood && insight.mood !== "calm" && <span className="text-xs text-muted-foreground">{t(`ai.mood.${insight.mood}`)}</span>}
      </div>
    </div>
  );
}

/** Above the reply box: marks the text as a suggestion, shows what it's based on, and lets the agent drop it. */
export function DraftBar({
  suggestion,
  applied,
  onUse,
  onDiscard,
}: {
  suggestion: Suggestion;
  /** The suggestion is what's in the reply box. Otherwise it waits to be used. */
  applied: boolean;
  onUse: () => void;
  onDiscard: () => void;
}) {
  const { t } = useSupport();
  const link = "text-xs text-muted-foreground underline-offset-2 hover:text-foreground hover:underline";
  return (
    <div className="space-y-1.5 px-4 pt-3 text-xs">
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
        <span className="inline-flex items-center gap-1.5 text-muted-foreground">
          <Sparkles className="size-3.5 text-primary" />
          {t(applied ? "ai.draft" : "ai.draftWaiting")}
        </span>
        <span className="ms-auto flex items-center gap-3">
          {!applied && (
            <button type="button" onClick={onUse} className="text-xs font-medium text-primary underline-offset-2 hover:underline">
              {t("ai.useDraft")}
            </button>
          )}
          <button type="button" onClick={onDiscard} className={link}>
            {t("ai.discard")}
          </button>
        </span>
      </div>
      {applied && <SuggestionSources suggestion={suggestion} />}
    </div>
  );
}

/** What a suggested reply is based on, each with its link when it has one. */
export function SuggestionSources({ suggestion }: { suggestion: Suggestion }) {
  const { t } = useSupport();
  if (!suggestion.sources.length) return null;
  return (
    <ul className="flex flex-wrap items-center gap-1.5 text-xs">
      <li className="text-muted-foreground">{t("ai.sources")}</li>
      {suggestion.sources.map((source) => {
        const label = source.type === "guidance" ? t("ai.guidance") : source.title;
        const chip = "inline-flex max-w-56 items-center rounded-md border bg-background px-1.5 py-0.5 text-foreground";
        return (
          <li key={source.id}>
            {source.url ? (
              <a href={source.url} target="_blank" rel="noopener noreferrer" className={cn(chip, "underline-offset-2 hover:underline")}>
                <bdi className="truncate">{label}</bdi>
              </a>
            ) : (
              <span className={chip} title={source.detail ?? undefined}>
                <bdi className="truncate">{label}</bdi>
              </span>
            )}
          </li>
        );
      })}
    </ul>
  );
}

export type RefineAction = "writeUp" | RefineInstruction;

const actionKey = (action: RefineAction) => (typeof action === "string" ? action : "custom");

/** Under the reply box whenever it holds text: quick rewrites, a free instruction, and Undo. */
export function RefineRow({
  busy,
  onRun,
  onUndo,
  translateTo,
  showWriteUp,
}: {
  /** The action in flight, if any. */
  busy: string | null;
  onRun: (action: RefineAction) => void;
  /** Present after a rewrite. */
  onUndo: (() => void) | null;
  /** The customer's language, when it isn't the agent's. */
  translateTo: string | null;
  /** The text is the agent's own notes, not a suggestion or a rewrite. */
  showWriteUp: boolean;
}) {
  const { t, locale } = useSupport();
  const [instruction, setInstruction] = useState("");
  const actions: { action: RefineAction; label: string }[] = [
    ...(showWriteUp ? [{ action: "writeUp" as const, label: t("ai.writeUp") }] : []),
    { action: "shorter", label: t("ai.shorter") },
    { action: "friendlier", label: t("ai.friendlier") },
    { action: "formal", label: t("ai.formal") },
    ...(translateTo ? [{ action: "translate" as const, label: t("ai.translateTo", { language: languageName(translateTo, locale) }) }] : []),
  ];
  const submit = () => {
    const custom = instruction.trim();
    if (!custom || busy) return;
    onRun({ custom });
    setInstruction("");
  };

  return (
    <div className="flex flex-wrap items-center gap-1.5 border-t px-3 py-2">
      <Sparkles className="ms-1 size-3.5 shrink-0 text-primary" aria-hidden />
      {actions.map(({ action, label }) => (
        <Button key={actionKey(action)} type="button" variant="outline" size="sm" className="h-7 px-2 text-xs" disabled={busy !== null} onClick={() => onRun(action)}>
          {busy === actionKey(action) && <Loader2 className="size-3 animate-spin" />}
          {label}
        </Button>
      ))}
      <div className="relative min-w-40 flex-1">
        <input
          value={instruction}
          onChange={(e) => setInstruction(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              submit();
            }
          }}
          disabled={busy !== null}
          placeholder={t("ai.instruction")}
          aria-label={t("ai.instruction")}
          dir="auto"
          className="h-7 w-full rounded-md border bg-background ps-2 pe-8 text-xs outline-none placeholder:text-muted-foreground focus-visible:ring-2 focus-visible:ring-ring/50 disabled:opacity-60"
        />
        {(instruction.trim() || busy === "custom") && (
          <button
            type="button"
            onClick={submit}
            disabled={busy !== null}
            aria-label={t("ai.apply")}
            className="absolute end-1 top-1/2 grid size-5 -translate-y-1/2 place-items-center rounded bg-primary text-primary-foreground disabled:opacity-60"
          >
            {busy === "custom" ? <Loader2 className="size-3 animate-spin" /> : <ArrowUp className="size-3" />}
          </button>
        )}
      </div>
      {onUndo && (
        <Button type="button" variant="ghost" size="sm" className="h-7 px-2 text-xs" disabled={busy !== null} onClick={onUndo}>
          <Undo2 className="size-3" />
          {t("ai.undo")}
        </Button>
      )}
    </div>
  );
}

/** A customer's message in the agent's language, fetched once on request. */
export function useMessageTranslation(messageId: string) {
  const { client, locale } = useSupport();
  const [shown, setShown] = useState(false);
  const translation = useMutation({ mutationFn: () => client.ai!.translate({ messageId, to: locale }) });
  return {
    text: shown ? translation.data?.text ?? null : null,
    pending: translation.isPending,
    failed: translation.isError,
    toggle() {
      if (shown) return setShown(false);
      setShown(true);
      if (!translation.data) translation.mutate();
    },
  };
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Loader2, Mic, Square } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { useSupport } from "./provider";

/*
 * Voice in the reply box: the agent speaks, and what they said becomes notes to write up, a
 * change to the reply, or plain text. With `client.ai.transcribe` the recording goes to your
 * transcription model. Without it, the browser's own speech recognition is used where it exists.
 * With neither, there is no microphone button.
 */

/** Where speech becomes text. */
export type VoiceEngine = "server" | "browser";
/** What happens with what was said. */
export type VoiceIntent = "writeUp" | "instruction" | "insert";
export type VoicePhase = "idle" | "starting" | "listening" | "transcribing" | "applying" | "failed";
type VoiceError = "denied" | "noMicrophone" | "unavailable" | "nothing" | "transcribe" | "apply";

/** Recordings stop here on their own, and what was said is applied. */
export const VOICE_MAX_SECONDS = 120;

// The Web Speech API isn't in every TypeScript DOM library, so only what's used is described.
type RecognitionResult = { isFinal: boolean; 0: { transcript: string } };
type Recognition = {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  onresult: ((event: { results: ArrayLike<RecognitionResult> }) => void) | null;
  onerror: ((event: { error: string }) => void) | null;
  onend: (() => void) | null;
  start(): void;
  stop(): void;
  abort(): void;
};

function recognitionConstructor(): (new () => Recognition) | null {
  if (typeof window === "undefined") return null;
  const scope = window as unknown as { SpeechRecognition?: new () => Recognition; webkitSpeechRecognition?: new () => Recognition };
  return scope.SpeechRecognition ?? scope.webkitSpeechRecognition ?? null;
}

const canRecord = () => typeof navigator !== "undefined" && Boolean(navigator.mediaDevices?.getUserMedia) && typeof MediaRecorder !== "undefined";
/** Phones and tablets: their speech recognition wants the microphone to itself and ends after each phrase. */
const isTouch = () => typeof window !== "undefined" && window.matchMedia?.("(pointer: coarse)").matches;

/** Known after mount: how this browser can listen, if at all, and the shortcut as this keyboard shows it. */
export function useVoiceEngine() {
  const { client } = useSupport();
  const server = Boolean(client.ai?.transcribe);
  const [state, setState] = useState<{ engine: VoiceEngine | null; shortcut: string | null }>({ engine: null, shortcut: null });
  useEffect(() => {
    const engine = server && canRecord() ? "server" : recognitionConstructor() ? "browser" : null;
    const shortcut = isTouch() ? null : /Mac|iPhone|iPad/.test(navigator.platform) ? "⌘⇧Space" : "Ctrl+Shift+Space";
    setState({ engine, shortcut });
  }, [server]);
  return state;
}

function microphoneError(error: unknown): VoiceError {
  const name = error instanceof Error ? error.name : "";
  if (name === "NotAllowedError" || name === "SecurityError") return "denied";
  if (name === "NotFoundError" || name === "OverconstrainedError") return "noMicrophone";
  return "unavailable";
}

type Session = {
  stream: MediaStream | null;
  recorder: MediaRecorder | null;
  chunks: Blob[];
  recognition: Recognition | null;
  /** What earlier recognition rounds settled on; the browser may end a round at every pause. */
  settled: string;
  /** The current round, settled and tentative. */
  current: string;
  finishing: boolean;
  fatal: VoiceError | null;
  limit: ReturnType<typeof setTimeout> | null;
};

/**
 * One voice session at a time. `resolve` gets what was said and returns the change to make, which
 * only runs if the agent hasn't cancelled in the meantime.
 */
export function useVoice({ engine, resolve }: { engine: VoiceEngine | null; resolve: (said: string) => Promise<() => void> }) {
  const { client, speechLocale } = useSupport();
  const [phase, setPhase] = useState<VoicePhase>("idle");
  const [transcript, setTranscript] = useState("");
  const [error, setError] = useState<{ kind: VoiceError; message?: string } | null>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [startedAt, setStartedAt] = useState<number | null>(null);
  const phaseRef = useRef<VoicePhase>("idle");
  const run = useRef(0);
  const session = useRef<Session | null>(null);
  const retryRef = useRef<(() => void) | null>(null);
  const latestResolve = useRef(resolve);
  useEffect(() => {
    latestResolve.current = resolve;
  });

  const go = (next: VoicePhase) => {
    phaseRef.current = next;
    setPhase(next);
  };

  /** Lets go of the microphone. Nothing recorded is kept. */
  const release = () => {
    const s = session.current;
    session.current = null;
    if (!s) return;
    if (s.limit) clearTimeout(s.limit);
    if (s.recorder && s.recorder.state !== "inactive") {
      s.recorder.onstop = null;
      s.recorder.stop();
    }
    if (s.recognition) {
      s.recognition.onresult = s.recognition.onerror = s.recognition.onend = null;
      try {
        s.recognition.abort();
      } catch {
        // Already stopped.
      }
    }
    s.stream?.getTracks().forEach((track) => track.stop());
    setStream(null);
    setStartedAt(null);
  };

  const fail = (kind: VoiceError, retry: (() => void) | null, message?: string) => {
    release();
    retryRef.current = retry;
    setError({ kind, message });
    go("failed");
  };

  const deliver = async (said: string, id: number) => {
    release();
    const text = said.replace(/\s+/g, " ").trim();
    if (!text) return fail("nothing", start);
    setTranscript(text);
    setError(null);
    go("applying");
    try {
      const commit = await latestResolve.current(text);
      if (run.current !== id) return;
      commit();
      setTranscript("");
      go("idle");
    } catch (e) {
      if (run.current !== id) return;
      fail("apply", () => void deliver(text, id), e instanceof Error && e.message ? e.message : undefined);
    }
  };

  const transcribeRecording = async (audio: Blob, id: number) => {
    release();
    if (!audio.size) return fail("nothing", start);
    setError(null);
    go("transcribing");
    let text: string;
    try {
      text = (await client.ai!.transcribe!({ audio })).text;
    } catch {
      if (run.current === id) fail("transcribe", () => void transcribeRecording(audio, id));
      return;
    }
    if (run.current === id) await deliver(text, id);
  };

  const listenInBrowser = (s: Session, id: number) => {
    const Recognition = recognitionConstructor()!;
    const recognition = new Recognition();
    s.recognition = recognition;
    recognition.lang = speechLocale;
    recognition.interimResults = true;
    recognition.continuous = !isTouch();
    recognition.onresult = (event) => {
      let heard = "";
      for (let i = 0; i < event.results.length; i++) heard += event.results[i]![0].transcript;
      s.current = heard;
      setTranscript(`${s.settled} ${heard}`.replace(/\s+/g, " ").trim());
    };
    recognition.onerror = (event) => {
      if (event.error === "not-allowed" || event.error === "service-not-allowed") s.fatal = "denied";
      else if (event.error === "audio-capture") s.fatal = "noMicrophone";
      else if (event.error === "network" || event.error === "language-not-supported") s.fatal = "unavailable";
    };
    recognition.onend = () => {
      if (run.current !== id || session.current !== s) return;
      s.settled = `${s.settled} ${s.current}`.trim();
      s.current = "";
      if (s.fatal && !s.settled) return fail(s.fatal, start);
      if (s.finishing || s.fatal) return void deliver(s.settled, id);
      // The browser ended the round at a pause. Keep listening until the agent says they're done.
      try {
        recognition.start();
      } catch {
        void deliver(s.settled, id);
      }
    };
    recognition.start();
  };

  async function start() {
    if (!engine || (phaseRef.current !== "idle" && phaseRef.current !== "failed")) return;
    const id = ++run.current;
    setTranscript("");
    setError(null);
    go("starting");
    const s: Session = { stream: null, recorder: null, chunks: [], recognition: null, settled: "", current: "", finishing: false, fatal: null, limit: null };
    session.current = s;
    try {
      // On a phone the browser's recognition needs the microphone to itself, so there's no level to show.
      if (engine === "server" || !isTouch()) {
        if (!navigator.mediaDevices?.getUserMedia) throw new DOMException("No microphone access", "NotFoundError");
        const media = await navigator.mediaDevices.getUserMedia({ audio: true });
        if (run.current !== id) return media.getTracks().forEach((track) => track.stop());
        s.stream = media;
        setStream(media);
      }
      if (engine === "server") {
        const mimeType = ["audio/webm;codecs=opus", "audio/mp4", "audio/ogg;codecs=opus"].find((type) => MediaRecorder.isTypeSupported(type));
        // Speech needs little: two minutes stay under half a megabyte.
        const recorder = new MediaRecorder(s.stream!, { ...(mimeType ? { mimeType } : {}), audioBitsPerSecond: 32_000 });
        s.recorder = recorder;
        recorder.ondataavailable = (event) => {
          if (event.data.size) s.chunks.push(event.data);
        };
        recorder.onstop = () => void transcribeRecording(new Blob(s.chunks, { type: recorder.mimeType || mimeType || "audio/webm" }), id);
        recorder.start();
      } else {
        listenInBrowser(s, id);
      }
    } catch (e) {
      if (run.current === id) fail(microphoneError(e), start);
      return;
    }
    s.limit = setTimeout(stop, VOICE_MAX_SECONDS * 1000);
    setStartedAt(Date.now());
    go("listening");
  }

  /** The agent is done speaking: apply what was said. */
  function stop() {
    const s = session.current;
    if (!s || phaseRef.current !== "listening" || s.finishing) return;
    s.finishing = true;
    if (s.limit) clearTimeout(s.limit);
    if (s.recorder) return s.recorder.stop();
    const id = run.current;
    try {
      s.recognition?.stop();
    } catch {
      // Between rounds: the fallback below delivers.
    }
    // Some browsers never report the end of a round they were asked to stop.
    s.limit = setTimeout(() => {
      if (run.current === id && session.current === s) void deliver(`${s.settled} ${s.current}`, id);
    }, 1500);
  }

  /** Drops everything: the recording, the transcript and any change still on its way. */
  function cancel() {
    run.current++;
    release();
    retryRef.current = null;
    setTranscript("");
    setError(null);
    go("idle");
  }

  useEffect(
    () => () => {
      run.current++;
      release();
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    []
  );

  return {
    phase,
    transcript,
    error,
    stream,
    startedAt,
    start: () => void start(),
    stop,
    cancel,
    retry: () => (retryRef.current ?? start)(),
  };
}

export type Voice = ReturnType<typeof useVoice>;

/** The one microphone control: starts listening, and stops when pressed again. */
export function VoiceButton({ voice, shortcut }: { voice: Voice; shortcut: string | null }) {
  const { t } = useSupport();
  const listening = voice.phase === "listening";
