  return (
    <Button
      type="button"
      variant="ghost"
      size="sm"
      aria-label={label}
      aria-pressed={voice.phase !== "idle"}
      title={shortcut ? `${label} (${shortcut})` : label}
      disabled={voice.phase !== "idle" && !listening}
      onClick={listening ? voice.stop : voice.start}
      className={cn(voice.phase !== "idle" && "text-primary")}
