/** Shown in the reply box from the moment the microphone is asked for until what was said is applied. */
export function VoicePanel({
  voice,
  intent,
  intents,
  onIntent,
}: {
  voice: Voice;
  intent: VoiceIntent;
  /** What the agent can choose between here. One choice shows no control. */
  intents: VoiceIntent[];
  onIntent: (intent: VoiceIntent) => void;
}) {
  const { t } = useSupport();
  const { phase, transcript, error } = voice;
  const done = useRef<HTMLButtonElement>(null);
  // Focus goes to Done, so Space or Enter ends the recording without reaching for the mouse.
  useEffect(() => {
    if (phase === "listening") done.current?.focus();
  }, [phase]);
  if (phase === "idle") return null;
  const working = phase === "transcribing" || phase === "applying";

  return (
    <div role="group" aria-label={t("ai.voice.label")} className="space-y-2.5 border-t px-4 py-3">
      <div aria-live="polite" className="min-h-10 text-sm">
        {phase === "failed" && error && <p className="text-destructive">{error.kind === "apply" ? error.message ?? t("ai.failed") : t(`ai.voice.errors.${error.kind}`)}</p>}
        {transcript ? (
          <p dir="auto" className={cn(phase === "failed" && "mt-1 text-muted-foreground")}>
            {transcript}
          </p>
        ) : (
          phase !== "failed" && (
            <p className="text-muted-foreground">
              {t(phase === "starting" ? "ai.voice.waiting" : phase === "transcribing" ? "ai.voice.transcribing" : `ai.voice.hint.${intent}`)}
            </p>
          )
        )}
      </div>
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
        {intents.length > 1 && phase !== "failed" && (
          <div role="radiogroup" aria-label={t("ai.voice.intentLabel")} className="inline-flex rounded-md border bg-background p-0.5">
            {intents.map((option) => (
              <button
                key={option}
                type="button"
                role="radio"
                aria-checked={intent === option}
                disabled={working}
                onClick={() => onIntent(option)}
                className={cn(
                  "rounded px-2 py-1 text-xs font-medium transition-colors disabled:opacity-60",
                  intent === option ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"
                )}
              >
                {t(`ai.voice.intent.${option}`)}
              </button>
            ))}
          </div>
        )}
        <div className="ms-auto flex items-center gap-2">
          {phase === "listening" && (
            <span className="flex items-center gap-2 text-xs text-muted-foreground tabular-nums">
              <VoiceLevel stream={voice.stream} />
              {voice.startedAt !== null && <VoiceClock startedAt={voice.startedAt} />}
            </span>
          )}
          {working && (
            <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <Loader2 className="size-3.5 animate-spin" />
              {phase === "applying" && intent !== "insert" && t(`ai.voice.applying.${intent}`)}
            </span>
          )}
          <Button type="button" variant="ghost" size="sm" onClick={voice.cancel}>
            {t(phase === "failed" ? "ai.voice.dismiss" : "actions.cancel")}
          </Button>
          {phase === "listening" && (
            <Button ref={done} type="button" size="sm" onClick={voice.stop}>
              <Square className="size-3 fill-current" />
              {t("ai.voice.stop")}
            </Button>
          )}
          {phase === "failed" && (
            <Button type="button" size="sm" onClick={voice.retry}>
              {t("actions.retry")}
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

const BARS = 16;

/** How loud the microphone hears the agent, as the last second and a half of bars. A dot when the level can't be read. */
function VoiceLevel({ stream }: { stream: MediaStream | null }) {
  const bars = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const AudioContextClass = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!stream || !AudioContextClass) return;
    const context = new AudioContextClass();
    void context.resume().catch(() => {});
    const analyser = context.createAnalyser();
    analyser.fftSize = 512;
    context.createMediaStreamSource(stream).connect(analyser);
    const samples = new Uint8Array(analyser.fftSize);
    const levels = new Array<number>(BARS).fill(0);
    let frame = 0;
    let last = 0;
    const draw = (now: number) => {
      frame = requestAnimationFrame(draw);
      if (now - last < 90) return;
      last = now;
      analyser.getByteTimeDomainData(samples);
      let sum = 0;
      for (const sample of samples) sum += ((sample - 128) / 128) ** 2;
      levels.shift();
      // Speech sits low on the scale: lift it so a normal voice fills the bars.
      levels.push(Math.min(1, Math.sqrt(sum / samples.length) * 5));
      const children = bars.current?.children;
      for (let i = 0; children && i < children.length; i++) (children[i] as HTMLElement).style.height = `${Math.max(12, levels[i]! * 100)}%`;
    };
    frame = requestAnimationFrame(draw);
    return () => {
      cancelAnimationFrame(frame);
      void context.close().catch(() => {});
    };
  }, [stream]);

  return (
    <span className="flex items-center gap-2" aria-hidden>
      <span className="size-2 animate-pulse rounded-full bg-red-500" />
      {stream && (
        <span ref={bars} className="flex h-5 items-center gap-0.5">
          {Array.from({ length: BARS }, (_, i) => (
            <span key={i} className="w-0.5 rounded-full bg-primary" style={{ height: "12%" }} />
          ))}
        </span>
      )}
    </span>
  );
}

const clock = (seconds: number) => `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;

/** Time spoken, against the limit. */
function VoiceClock({ startedAt }: { startedAt: number }) {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const tick = () => setSeconds(Math.min(VOICE_MAX_SECONDS, Math.floor((Date.now() - startedAt) / 1000)));
    tick();
    const timer = setInterval(tick, 250);
    return () => clearInterval(timer);
  }, [startedAt]);
  return (
    <span className={cn(VOICE_MAX_SECONDS - seconds <= 15 && "text-amber-700 dark:text-amber-300")}>
      {clock(seconds)} / {clock(VOICE_MAX_SECONDS)}
    </span>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Check, Copy, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useSupport } from "./provider";
import type { ApprovedAnswer } from "./client";
import { markdownToText } from "./format";
import { languageName } from "./ai";

/*
 * Memory: what the team teaches AI while answering. The dialog that saves an approved answer,
 * the one that drafts an article, and the list an agent picks an answer from in the reply box.
 * Each part appears only when the client has the method behind it.
 */

const base = (code: string) => code.toLowerCase().split("-")[0]!;
/** The languages an answer can be kept to. One that isn't listed still shows when an answer already has it. */
const LANGUAGES = ["ar", "cs", "da", "de", "el", "en", "es", "fi", "fr", "he", "hi", "id", "it", "ja", "ko", "nb", "nl", "pl", "pt", "ro", "ru", "sv", "th", "tr", "uk", "vi", "zh"];

const message = (error: unknown, fallback: string) => (error instanceof Error && error.message ? error.message : fallback);

/**
 * Saves an approved answer: from a reply (its customer details are taken out first, for the agent
 * to review), for a gap, from an article, or an existing one to change.
 */
export function ApprovedAnswerDialog({
  open,
  onOpenChange,
  from,
  answer,
  gap,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** A sent reply or a draft, generalised when the dialog opens. */
  from?: { ticketId: string; text: string };
  /** The answer to change. */
  answer?: ApprovedAnswer;
  /** The gap this answer resolves. Its theme starts as the title. */
  gap?: { id: string; theme: string };
}) {
  const { client, t, locale } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const [title, setTitle] = useState("");
  const [text, setText] = useState("");
  /** Null: for customers writing in any language. */
  const [language, setLanguage] = useState<string | null>(null);

  const generalise = useMutation({
    mutationFn: (input: { ticketId: string; text: string }) => ai!.generaliseAnswer!(input),
    onSuccess: (result) => {
      setTitle(result.title);
      setText(result.text);
      // An answer in a language the team doesn't work in is most likely for the customers who write in it.
      setLanguage(result.language && base(result.language) !== base(locale) ? base(result.language) : null);
    },
  });
  const save = useMutation({
    mutationFn: () =>
      ai!.saveApprovedAnswer!({
        ...(answer ? { id: answer.id } : {}),
        title: title.trim(),
        text: text.trim(),
        language,
        ...(from ? { ticketId: from.ticketId } : {}),
        ...(gap ? { gapId: gap.id } : {}),
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["support", "ai", "answers"] });
      queryClient.invalidateQueries({ queryKey: ["support", "ai", "gaps"] });
      onOpenChange(false);
    },
  });

  useEffect(() => {
    if (!open) return;
    save.reset();
    generalise.reset();
    setTitle(answer?.title ?? gap?.theme ?? "");
    setText(answer?.text ?? from?.text ?? "");
    setLanguage(answer?.language ?? null);
    if (from && ai?.generaliseAnswer) generalise.mutate(from);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  if (!ai?.saveApprovedAnswer) return null;
  const preparing = generalise.isPending;
  const languages = [...new Set([...LANGUAGES, ...(language ? [language] : [])])]
    .map((code) => ({ code, name: languageName(code, locale) }))
    .sort((a, b) => a.name.localeCompare(b.name, locale));

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-xl">
        <DialogHeader>
          <DialogTitle>{t(answer ? "ai.answers.editTitle" : from ? "ai.answers.saveTitle" : "ai.answers.newTitle")}</DialogTitle>
          <DialogDescription>{t(from ? "ai.answers.fromReplyDescription" : "ai.answers.description")}</DialogDescription>
        </DialogHeader>
        {preparing ? (
          <div className="grid gap-3" aria-busy>
            <Skeleton className="h-9" />
            <Skeleton className="h-40" />
            <p className="text-sm text-muted-foreground">{t("ai.answers.preparing")}</p>
          </div>
        ) : (
          <form
            className="grid gap-4"
            onSubmit={(e) => {
              e.preventDefault();
              if (title.trim() && text.trim()) save.mutate();
            }}
          >
            {generalise.isError && <p className="text-sm text-amber-700 dark:text-amber-300">{t("ai.answers.notGeneralised")}</p>}
            <div className="grid gap-1.5">
              <label htmlFor="support-answer-title" className="text-sm font-medium">
                {t("ai.answers.title")}
              </label>
              <Input id="support-answer-title" dir="auto" value={title} maxLength={200} onChange={(e) => setTitle(e.target.value)} placeholder={t("ai.answers.titlePlaceholder")} />
            </div>
            <div className="grid gap-1.5">
              <label htmlFor="support-answer-text" className="text-sm font-medium">
                {t("ai.answers.text")}
              </label>
              <Textarea id="support-answer-text" dir="auto" value={text} onChange={(e) => setText(e.target.value)} className="max-h-[45vh] min-h-40" />
              <p className="text-xs text-muted-foreground">{t("ai.answers.placeholders", { name: "{name}", company: "{company}", agent: "{agent}" })}</p>
            </div>
            <div className="flex items-center justify-between gap-4">
              <label htmlFor="support-answer-language" className="text-sm font-medium">
                {t("ai.answers.language")}
              </label>
              {/* A native select: the same in Radix and Base UI projects, and at home on a phone. */}
              <select
                id="support-answer-language"
                value={language ?? ""}
                onChange={(e) => setLanguage(e.target.value || null)}
                className="h-9 max-w-56 rounded-md border bg-background px-2 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
              >
                <option value="">{t("ai.answers.anyLanguage")}</option>
                {languages.map(({ code, name }) => (
                  <option key={code} value={code}>
                    {name}
                  </option>
                ))}
              </select>
            </div>
            {save.error && <p className="text-sm text-destructive">{message(save.error, t("errors.send"))}</p>}
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
                {t("actions.cancel")}
              </Button>
              <Button type="submit" disabled={!title.trim() || !text.trim() || save.isPending}>
                {save.isPending && <Loader2 className="size-4 animate-spin" />}
                {t(answer ? "ai.settings.save" : "ai.answers.save")}
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

/** Drafts a help article from how agents answered: a gap's tickets, or the tickets given. The team copies it to its docs or saves it as an approved answer. */
export function ArticleDialog({
  open,
  onOpenChange,
  from,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  from: { gapId: string } | { ticketIds: string[] };
}) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const [title, setTitle] = useState("");
  const [markdown, setMarkdown] = useState("");
  const [copied, setCopied] = useState(false);

  const draft = useMutation({
    mutationFn: () => ai!.draftArticle!(from),
    onSuccess: (article) => {
      setTitle(article.title);
      setMarkdown(article.markdown);
    },
  });
  const save = useMutation({
    mutationFn: () =>
      ai!.saveApprovedAnswer!({ title: title.trim(), text: markdownToText(markdown), language: null, ...("gapId" in from ? { gapId: from.gapId } : {}) }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["support", "ai", "answers"] });
      queryClient.invalidateQueries({ queryKey: ["support", "ai", "gaps"] });
      onOpenChange(false);
    },
  });

  useEffect(() => {
    if (!open) return;
    save.reset();
    setCopied(false);
    draft.mutate();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  if (!ai?.draftArticle) return null;
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(`# ${title.trim()}\n\n${markdown.trim()}\n`);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // No clipboard access: the text is selectable in the box.
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{t("ai.article.title")}</DialogTitle>
          <DialogDescription>{t("ai.article.description")}</DialogDescription>
        </DialogHeader>
        {draft.isPending ? (
          <div className="grid gap-3" aria-busy>
            <Skeleton className="h-9" />
            <Skeleton className="h-56" />
            <p className="text-sm text-muted-foreground">{t("ai.article.writing")}</p>
          </div>
        ) : draft.isError ? (
          <>
            <p className="text-sm text-destructive">{message(draft.error, t("ai.failed"))}</p>
            <DialogFooter>
              <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
                {t("actions.cancel")}
              </Button>
              <Button type="button" onClick={() => draft.mutate()}>
                {t("actions.retry")}
              </Button>
            </DialogFooter>
          </>
        ) : (
          <div className="grid gap-4">
            <Input dir="auto" value={title} onChange={(e) => setTitle(e.target.value)} aria-label={t("ai.article.heading")} />
            <Textarea dir="auto" value={markdown} onChange={(e) => setMarkdown(e.target.value)} aria-label={t("ai.article.body")} className="max-h-[50vh] min-h-56 font-mono text-xs" />
            {save.error && <p className="text-sm text-destructive">{message(save.error, t("errors.send"))}</p>}
            <DialogFooter>
              {ai.saveApprovedAnswer && (
                <Button type="button" variant="outline" disabled={!title.trim() || !markdown.trim() || save.isPending} onClick={() => save.mutate()}>
                  {save.isPending && <Loader2 className="size-4 animate-spin" />}
                  {t("ai.answers.saveReply")}
                </Button>
              )}
              <Button type="button" disabled={!markdown.trim()} onClick={copy}>
                {copied ? <Check className="size-4" /> : <Copy className="size-4" />}
                {t(copied ? "ai.article.copied" : "ai.article.copy")}
              </Button>
            </DialogFooter>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

/** The approved answers that fit what an agent typed after "/", best first. */
export function matchAnswers(answers: ApprovedAnswer[], query: string, language: string | null) {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  return answers
    .filter((answer) => !answer.language || !language || base(answer.language) === base(language))
    .map((answer) => {
      const title = answer.title.toLowerCase();
      const body = answer.text.toLowerCase();
      if (!words.every((word) => title.includes(word) || body.includes(word))) return null;
      // A match in the title counts for more, and an answer written for this language comes first.
      return { answer, score: words.filter((word) => title.includes(word)).length * 2 + (answer.language ? 1 : 0) };
    })
    .filter((match): match is { answer: ApprovedAnswer; score: number } => match !== null)
    .sort((a, b) => b.score - a.score || a.answer.title.localeCompare(b.answer.title))
    .map((match) => match.answer);
}

export const answerOptionId = (id: string) => `support-answer-${id}`;

/** The list above the reply box while an agent types "/". The reply box keeps the focus and the keys. */
export function AnswerPicker({
  answers,
  active,
  onActive,
  onChoose,
}: {
  answers: ApprovedAnswer[];
  /** The highlighted answer's index. */
  active: number;
  onActive: (index: number) => void;
  onChoose: (answer: ApprovedAnswer) => void;
}) {
  const { t } = useSupport();
  useEffect(() => {
    const id = answers[active]?.id;
    if (id) document.getElementById(answerOptionId(id))?.scrollIntoView({ block: "nearest" });
  }, [active, answers]);
  return (
    <div className="absolute inset-x-3 bottom-full z-20 mb-1 max-w-lg overflow-hidden rounded-lg border bg-popover text-popover-foreground shadow-md">
      {answers.length ? (
        <ul role="listbox" id="support-answers" aria-label={t("ai.answers.heading")} className="max-h-64 overflow-y-auto p-1">
          {answers.map((answer, index) => (
            <li
              key={answer.id}
              id={answerOptionId(answer.id)}
              role="option"
              aria-selected={index === active}
              onMouseEnter={() => onActive(index)}
              // The reply box must not lose focus to the click.
              onMouseDown={(e) => e.preventDefault()}
              onClick={() => onChoose(answer)}
              className={cn("cursor-pointer rounded-md px-2.5 py-1.5", index === active && "bg-accent text-accent-foreground")}
            >
              <p dir="auto" className="truncate text-sm font-medium">
                {answer.title}
              </p>
              <p dir="auto" className="truncate text-xs text-muted-foreground">
                {answer.text.replace(/\s+/g, " ")}
              </p>
            </li>
          ))}
        </ul>
      ) : (
        <p className="px-3 py-2.5 text-sm text-muted-foreground">{t("ai.answers.noMatch")}</p>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { AlertCircle, Check, Loader2, Zap } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useSupport, type Translate } from "./provider";
import type { ActionField, ActionRun, ProposedAction, TicketAction, TicketDetail } from "./client";

/*
 * Actions: what AI and agents can do in your product from a ticket. The cards under a suggested
 * reply (approve or skip what it assumes), the dialog that runs one by hand, and the small form
 * both share. Each part appears only when the client has `runAction`.
 */

type Values = Record<string, string | boolean>;

/** An action's input as what its form fields hold. */
export function toValues(fields: ActionField[], input: Record<string, unknown> = {}): Values {
  return Object.fromEntries(
    fields.map((field) => {
      const value = input[field.name];
      if (field.kind === "boolean") return [field.name, value === true];
      if (field.kind === "json") return [field.name, value === undefined ? "" : JSON.stringify(value, null, 2)];
      return [field.name, value === undefined || value === null ? "" : String(value)];
    })
  );
}

/** What the form holds as the action's input, or the field that still needs a valid value. */
export function fromValues(fields: ActionField[], values: Values): { input: Record<string, unknown> } | { invalid: ActionField } {
  const input: Record<string, unknown> = {};
  for (const field of fields) {
    const value = values[field.name];
    if (field.kind === "boolean") {
      input[field.name] = value === true;
      continue;
    }
    const text = String(value ?? "").trim();
    if (!text) {
      if (field.required) return { invalid: field };
      continue;
    }
    if (field.kind === "number") {
      const number = Number(text);
      if (!Number.isFinite(number)) return { invalid: field };
      input[field.name] = number;
    } else if (field.kind === "json") {
      try {
        input[field.name] = JSON.parse(text);
      } catch {
        return { invalid: field };
      }
    } else input[field.name] = text;
  }
  return { input };
}

const control = "h-8 w-full rounded-md border bg-background px-2 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring/50 disabled:opacity-60";

/** One control per input: text, number, date, a switch, a select for fixed choices, JSON for anything else. */
export function ActionFields({
  id,
  fields,
  values,
  onChange,
  disabled,
  className,
}: {
  /** Makes each control's id unique on the page. */
  id: string;
  fields: ActionField[];
  values: Values;
  onChange: (values: Values) => void;
  disabled?: boolean;
  className?: string;
}) {
  if (!fields.length) return null;
  const set = (name: string, value: string | boolean) => onChange({ ...values, [name]: value });
  return (
    <div className={cn("grid gap-3", className)}>
      {fields.map((field) => {
        const fieldId = `${id}-${field.name}`;
        const value = values[field.name];
        const label = (
          <label htmlFor={fieldId} className="text-xs font-medium">
            {field.label}
          </label>
        );
        if (field.kind === "boolean") {
          return (
            <div key={field.name} className="flex items-center justify-between gap-3" title={field.description ?? undefined}>
              {label}
              <Switch id={fieldId} checked={value === true} disabled={disabled} onCheckedChange={(checked) => set(field.name, Boolean(checked))} />
            </div>
          );
        }
        return (
          <div key={field.name} className={cn("grid gap-1", field.kind === "json" && "sm:col-span-full")} title={field.description ?? undefined}>
            {label}
            {field.kind === "select" ? (
              // A native select: the same in Radix and Base UI projects, and at home on a phone.
              <select id={fieldId} value={String(value ?? "")} disabled={disabled} onChange={(e) => set(field.name, e.target.value)} className={control}>
                {(!field.required || !value) && <option value="" />}
                {field.options?.map((option) => (
                  <option key={option} value={option}>
                    {option}
                  </option>
                ))}
              </select>
            ) : field.kind === "json" ? (
              <Textarea id={fieldId} dir="ltr" value={String(value ?? "")} disabled={disabled} onChange={(e) => set(field.name, e.target.value)} className="min-h-20 font-mono text-xs" spellCheck={false} />
            ) : (
              <Input
                id={fieldId}
                type={field.kind === "number" ? "number" : field.kind === "date" ? "date" : "text"}
                dir="auto"
                value={String(value ?? "")}
                disabled={disabled}
                onChange={(e) => set(field.name, e.target.value)}
                className="h-8"
              />
            )}
          </div>
        );
      })}
    </div>
  );
}

/** Why a run didn't go through, in words an agent can act on. Null when it did. */
export function runProblem(run: Pick<ActionRun, "status" | "summary">, title: string, t: Translate): string | null {
  if (run.status === "succeeded" || run.status === "running") return null;
  if (run.status === "failed") return run.summary ? t("ai.actions.errors.failedWith", { title, summary: run.summary }) : t("ai.actions.errors.failed", { title });
  return t(`ai.actions.errors.${run.status === "timed_out" ? "timedOut" : "errored"}`, { title });
}

const problem = (error: unknown, fallback: string) => (error instanceof Error && error.message ? error.message : fallback);

/** The proposed actions an agent hasn't decided on: what sending the reply should ask about first. */
export const undecidedActions = (actions: ProposedAction[] | undefined) => (actions ?? []).filter((action) => action.state === "proposed" || action.state === "failed");

/**
 * Under a suggested reply: each change the reply assumes, with what it will do, its inputs,
 * Approve and Skip. Approving runs it for this ticket's customer; skipping rewrites the reply.
 */
export function ProposedActions({
  ticketId,
  suggestionId,
  actions,
  text,
  onText,
}: {
  ticketId: string;
  suggestionId: string;
  actions: ProposedAction[];
  /** The reply box, when it holds the suggested reply: rewritten when an action is skipped or its inputs change. */
  text: string | null;
  onText: (text: string) => void;
}) {
  const { client } = useSupport();
  if (!client.ai?.runAction || !actions.length) return null;
  return (
    <ul className="space-y-2 px-4 pt-3">
      {actions.map((action) => (
        <ProposedActionCard key={action.name} ticketId={ticketId} suggestionId={suggestionId} action={action} text={text} onText={onText} />
      ))}
    </ul>
  );
}

function ProposedActionCard({
  ticketId,
  suggestionId,
  action,
  text,
  onText,
}: {
  ticketId: string;
  suggestionId: string;
  action: ProposedAction;
  text: string | null;
  onText: (text: string) => void;
}) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai!;
  const [values, setValues] = useState(() => toValues(action.fields, action.input));
  const [invalid, setInvalid] = useState<string | null>(null);
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["support", "ticket", ticketId] });

  const approve = useMutation({
    mutationFn: (input: Record<string, unknown>) => ai.runAction!({ ticketId, suggestionId, action: action.name, input, ...(text ? { text } : {}) }),
    onSuccess: (result) => {
      if (result.text) onText(result.text);
    },
    onSettled: refresh,
  });
  const skip = useMutation({
    mutationFn: () => ai.declineAction!({ ticketId, suggestionId, action: action.name, ...(text ? { text } : {}) }),
    onSuccess: (result) => {
      if (result.text) onText(result.text);
    },
    onSettled: refresh,
  });

  // What this agent just did shows at once; what the server says takes over when the ticket reloads.
  const run = approve.data?.run ?? action.run;
  const state: ProposedAction["state"] =
    approve.isPending || action.state === "running"
      ? "running"
      : run?.status === "succeeded"
        ? "done"
        : skip.isSuccess || action.state === "declined"
          ? "declined"
          : run && run.status !== "running"
            ? "failed"
            : "proposed";
  const busy = approve.isPending || skip.isPending;
  const failure = approve.isError ? problem(approve.error, t("ai.actions.errors.request")) : skip.isError ? problem(skip.error, t("ai.failed")) : state === "failed" && run ? runProblem(run, action.title, t) : null;

  const submit = () => {
    const parsed = fromValues(action.fields, values);
    if ("invalid" in parsed) return setInvalid(t("ai.actions.invalidField", { field: parsed.invalid.label }));
    setInvalid(null);
    approve.mutate(parsed.input);
  };

  if (state === "done" || state === "declined") {
    return (
      <li className="flex items-start gap-2 rounded-lg border bg-background px-3 py-2 text-sm">
        {state === "done" ? <Check className="mt-0.5 size-4 shrink-0 text-emerald-600 dark:text-emerald-400" aria-hidden /> : <Zap className="mt-0.5 size-4 shrink-0 text-muted-foreground" aria-hidden />}
        <p className={cn("min-w-0", state === "declined" && "text-muted-foreground")}>
          <span className="font-medium">{action.title}</span>
          <span dir="auto" className="text-muted-foreground">
            {" · "}
            {state === "done" ? run?.summary || t("ai.actions.done") : t("ai.actions.skipped")}
          </span>
        </p>
      </li>
    );
  }

  return (
    <li className="space-y-3 rounded-lg border bg-background p-3">
      <div className="flex flex-wrap items-start justify-between gap-x-3 gap-y-2">
        <div className="flex min-w-0 flex-1 basis-56 items-start gap-2">
          <Zap className="mt-0.5 size-4 shrink-0 text-primary" aria-hidden />
          <div className="min-w-0">
            <p className="text-sm font-medium">{action.title}</p>
            {action.reason && (
              <p dir="auto" className="text-xs text-muted-foreground">
                {action.reason}
              </p>
            )}
          </div>
        </div>
        <div className="flex shrink-0 items-center gap-1.5">
          {ai.declineAction && (
            <Button type="button" size="sm" variant="ghost" className="h-7 px-2 text-xs" disabled={busy || state === "running"} onClick={() => skip.mutate()}>
              {skip.isPending && <Loader2 className="size-3 animate-spin" />}
              {t("ai.actions.skip")}
            </Button>
          )}
          <Button type="button" size="sm" className="h-7 px-2.5 text-xs" disabled={busy || state === "running"} onClick={submit}>
            {(approve.isPending || state === "running") && <Loader2 className="size-3 animate-spin" />}
            {t(state === "failed" ? "actions.retry" : "ai.actions.approve")}
          </Button>
        </div>
      </div>
      <ActionFields
        id={`support-action-${suggestionId}-${action.name}`}
        fields={action.fields}
        values={values}
        onChange={setValues}
        disabled={busy || state === "running"}
        className="sm:grid-cols-2"
      />
      {(invalid || failure) && (
        <p className="flex items-start gap-1.5 text-xs text-destructive">
          <AlertCircle className="mt-0.5 size-3.5 shrink-0" aria-hidden />
          <span dir="auto">{invalid ?? failure}</span>
        </p>
      )}
    </li>
  );
}

/** What a lookup returned, when it's a flat list of values worth showing. */
function ResultData({ data }: { data: Record<string, unknown> }) {
  const rows = Object.entries(data).filter(([, value]) => ["string", "number", "boolean"].includes(typeof value));
  if (!rows.length) return null;
  return (
    <dl className="space-y-1.5 text-sm">
      {rows.map(([key, value]) => (
        <div key={key} className="flex justify-between gap-3">
          <dt className="shrink-0 text-muted-foreground">{key}</dt>
          <dd dir="auto" className="min-w-0 text-end break-words tabular-nums">
            {String(value)}
          </dd>
        </div>
      ))}
    </dl>
  );
}

/** Runs one action by hand, from the ticket's menu: its inputs, then what happened. */
export function RunActionDialog({ detail, action, onClose }: { detail: TicketDetail; action: TicketAction | null; onClose: () => void }) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  const ticketId = detail.ticket.id;
  const [values, setValues] = useState<Values>({});
  const [invalid, setInvalid] = useState<string | null>(null);
  const run = useMutation({
    mutationFn: (input: Record<string, unknown>) => client.ai!.runAction!({ ticketId, action: action!.name, input }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: ["support", "ticket", ticketId] }),
  });

  useEffect(() => {
    if (!action) return;
    run.reset();
    setInvalid(null);
    setValues(toValues(action.fields));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [action?.name]);

  if (!action) return null;
  const result = run.data?.run ?? null;
  const failure = run.isError ? problem(run.error, t("ai.actions.errors.request")) : result ? runProblem(result, action.title, t) : null;
  const done = result?.status === "succeeded";

  return (
    <Dialog open onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{action.title}</DialogTitle>
          <DialogDescription>{t("ai.actions.runFor", { customer: detail.customer?.name ?? "" })}</DialogDescription>
        </DialogHeader>
        {done ? (
          <div className="space-y-3">
            <p className="flex items-start gap-2 text-sm">
              <Check className="mt-0.5 size-4 shrink-0 text-emerald-600 dark:text-emerald-400" aria-hidden />
              <span dir="auto">{result.summary || t("ai.actions.done")}</span>
            </p>
            {result.data && <ResultData data={result.data} />}
            <DialogFooter>
              <Button type="button" variant="outline" onClick={onClose}>
                {t("ai.actions.close")}
              </Button>
            </DialogFooter>
          </div>
        ) : (
          <form
            className="grid gap-4"
            onSubmit={(e) => {
              e.preventDefault();
              const parsed = fromValues(action.fields, values);
              if ("invalid" in parsed) return setInvalid(t("ai.actions.invalidField", { field: parsed.invalid.label }));
              setInvalid(null);
              run.mutate(parsed.input);
            }}
          >
            <ActionFields id={`support-run-${action.name}`} fields={action.fields} values={values} onChange={setValues} disabled={run.isPending} />
            {(invalid || failure) && (
              <p className="flex items-start gap-1.5 text-sm text-destructive">
                <AlertCircle className="mt-0.5 size-4 shrink-0" aria-hidden />
                <span dir="auto">{invalid ?? failure}</span>
              </p>
            )}
            <DialogFooter>
              <Button type="button" variant="ghost" onClick={onClose}>
                {t("actions.cancel")}
              </Button>
              <Button type="submit" disabled={run.isPending}>
                {run.isPending && <Loader2 className="size-4 animate-spin" />}
                {t(result ? "actions.retry" : "ai.actions.run")}
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Flag, Loader2, Send } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useSupport } from "./provider";
import type { AutopilotExample, AutopilotMode, AutopilotOverview, AutopilotRecord, AutopilotTopic, Suggestion, TicketDetail, TimelineEvent, TimelineMessage } from "./client";
import { formatWhen } from "./format";
import { SuggestionSources, languageName } from "./ai";
import { MessageText } from "./parts";

/*
 * Autopilot: the readiness view in AI settings, where a team sees each topic's track record and
 * decides whether it answers on its own, and the two marks it leaves on a ticket: a held reply
 * an agent can stop, and a sent one an agent can flag. Each part appears only when the client
 * has the method behind it.
 */

const message = (error: unknown, fallback: string) => (error instanceof Error && error.message ? error.message : fallback);
const percent = (rate: number) => Math.floor(rate * 100);

const stageStyles: Record<AutopilotTopic["stage"], string> = {
  collecting: "bg-muted text-muted-foreground ring-border",
  eligible: "bg-emerald-50 text-emerald-700 ring-emerald-600/20 dark:bg-emerald-500/10 dark:text-emerald-300",
  on: "bg-primary text-primary-foreground ring-primary",
  paused: "bg-amber-50 text-amber-800 ring-amber-600/20 dark:bg-amber-500/10 dark:text-amber-300",
};

/** How the window's drafts ended. What went right is green, as the "Ready" it adds up to; what didn't is amber, grey and red. */
const PARTS: { key: "used" | "light" | "heavy" | "discarded" | "unhappy" | "flagged"; count: (r: AutopilotRecord) => number; className: string }[] = [
  { key: "used", count: (r) => r.usedAsIs, className: "bg-emerald-600 dark:bg-emerald-500" },
  { key: "light", count: (r) => r.lightlyEdited, className: "bg-emerald-600/45 dark:bg-emerald-500/45" },
  { key: "heavy", count: (r) => r.heavilyEdited, className: "bg-amber-500" },
  { key: "discarded", count: (r) => r.discarded, className: "bg-muted-foreground/50" },
  { key: "unhappy", count: (r) => r.cameBackUnhappy, className: "bg-red-400" },
  { key: "flagged", count: (r) => r.flagged, className: "bg-red-600" },
];

/** The Autopilot section of AI settings. */
export function AutopilotSettings() {
  const { client, t, locale } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const enabled = Boolean(ai?.getAutopilot && ai.setAutopilotTopic);
  const overview = useQuery({ queryKey: ["support", "ai", "autopilot"], queryFn: () => ai!.getAutopilot!(), enabled });
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["support", "ai", "autopilot"] });
  const stop = useMutation({ mutationFn: (stopped: boolean) => ai!.setAutopilot!({ stopped }), onSettled: refresh });
  const decide = useMutation({ mutationFn: (input: { topic: string; on: boolean; mode?: AutopilotMode }) => ai!.setAutopilotTopic!(input), onSettled: refresh });
  const [switchingOn, setSwitchingOn] = useState<AutopilotTopic | null>(null);
  const [reading, setReading] = useState<string | null>(null);
  if (!enabled) return null;
  const data = overview.data;

  return (
    <section className="space-y-3 border-t pt-6">
      <div className="flex flex-wrap items-start justify-between gap-x-4 gap-y-2">
        <div className="min-w-[14rem] flex-1 space-y-1">
          <h2 className="text-sm font-medium">{t("ai.autopilot.heading")}</h2>
          <p className="text-sm text-muted-foreground">{t("ai.autopilot.help")}</p>
        </div>
        {data && !data.stopped && ai?.setAutopilot && data.topics.some((topic) => topic.stage === "on") && (
          <Button type="button" variant="outline" size="sm" className="shrink-0" disabled={stop.isPending} onClick={() => stop.mutate(true)}>
            {stop.isPending && <Loader2 className="size-4 animate-spin" />}
            {t("ai.autopilot.stop")}
          </Button>
        )}
      </div>

      {data?.stopped && (
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-300/60 bg-amber-50 px-4 py-3 dark:border-amber-500/30 dark:bg-amber-500/10">
          <div className="text-sm">
            <p className="font-medium">{t("ai.autopilot.stopped")}</p>
            {data.stoppedBy && data.stoppedAt && (
              <p className="text-muted-foreground">{t("ai.autopilot.stoppedBy", { name: data.stoppedBy.name, when: formatWhen(data.stoppedAt, locale) })}</p>
            )}
          </div>
          {ai?.setAutopilot && (
            <Button type="button" size="sm" disabled={stop.isPending} onClick={() => stop.mutate(false)}>
              {stop.isPending && <Loader2 className="size-4 animate-spin" />}
              {t("ai.autopilot.start")}
            </Button>
          )}
        </div>
      )}
      {stop.error && <p className="text-sm text-destructive">{message(stop.error, t("ai.failed"))}</p>}

      {overview.error ? (
        <p className="text-sm text-destructive">{t("errors.load")}</p>
      ) : !data ? (
        <Skeleton className="h-32" />
      ) : data.topics.length ? (
        <>
          <ul className="divide-y rounded-xl border bg-card">
            {data.topics.map((topic) => (
              <TopicRow
                key={topic.topic}
                topic={topic}
                overview={data}
                busy={decide.isPending && decide.variables?.topic === topic.topic}
                error={decide.isError && decide.variables?.topic === topic.topic ? message(decide.error, t("ai.failed")) : null}
                onSwitchOn={() => setSwitchingOn(topic)}
                onDecide={(input) => decide.mutate({ topic: topic.topic, ...input })}
                onRead={ai?.autopilotExamples ? () => setReading(topic.topic) : undefined}
              />
            ))}
          </ul>
          <Bar overview={data} />
        </>
      ) : (
        <p className="rounded-xl border border-dashed px-4 py-6 text-center text-sm text-muted-foreground">{t("ai.autopilot.empty")}</p>
      )}

      {switchingOn && data && (
        <SwitchOnDialog
          topic={switchingOn}
          holdMinutes={data.holdMinutes}
          onClose={() => setSwitchingOn(null)}
          onConfirm={(mode) => {
            decide.mutate({ topic: switchingOn.topic, on: true, mode });
            setSwitchingOn(null);
          }}
        />
      )}
      {reading && <ExamplesDialog topic={reading} onClose={() => setReading(null)} />}
    </section>
  );
}

function TopicRow({
  topic,
  overview,
  busy,
  error,
  onSwitchOn,
  onDecide,
  onRead,
}: {
  topic: AutopilotTopic;
  overview: AutopilotOverview;
  busy: boolean;
  error: string | null;
  onSwitchOn: () => void;
  onDecide: (input: { on: boolean; mode?: AutopilotMode }) => void;
  onRead?: () => void;
}) {
  const { t, locale } = useSupport();
  const { record, stage } = topic;
  const counts = PARTS.map((part) => ({ ...part, value: part.count(record) })).filter((part) => part.value > 0);
  const aside = [
    record.sentByAutopilot > 0 && t("ai.autopilot.sentByAutopilot", { count: record.sentByAutopilot }),
    record.cannotAnswer > 0 && t("ai.autopilot.cannotAnswer", { count: record.cannotAnswer }),
    record.reopened > 0 && t("ai.autopilot.reopened", { count: record.reopened }),
  ].filter(Boolean);
  const judged = record.recent.drafts >= overview.minDrafts;

  return (
    <li className="space-y-2.5 px-4 py-4">
      <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
        <div className="flex min-w-0 items-center gap-2">
          <bdi className="truncate text-sm font-medium">{topic.topic}</bdi>
          <span className={cn("inline-flex shrink-0 items-center rounded-md px-1.5 py-0.5 text-[11px] font-medium ring-1 ring-inset", stageStyles[stage])}>
            {t(`ai.autopilot.stage.${stage}`)}
            {stage === "on" && topic.mode && ` · ${t(`ai.autopilot.mode.${topic.mode}`)}`}
          </span>
        </div>
        <div className="flex items-center gap-2">
          {busy && <Loader2 className="size-4 animate-spin text-muted-foreground" />}
          {stage === "eligible" && (
            <Button type="button" size="sm" disabled={busy} onClick={onSwitchOn}>
              {t("ai.autopilot.switchOn")}
            </Button>
          )}
          {stage === "paused" && (
            <Button type="button" size="sm" disabled={busy || !topic.ready} onClick={() => onDecide({ on: true })}>
              {t("ai.autopilot.resume")}
            </Button>
          )}
          {(stage === "on" || stage === "paused") && (
            <Button type="button" size="sm" variant="outline" disabled={busy} onClick={() => onDecide({ on: false })}>
              {t("ai.autopilot.switchOff")}
            </Button>
          )}
        </div>
      </div>

      {record.drafts > 0 && (
        <div className="flex h-1.5 overflow-hidden rounded-full bg-muted" aria-hidden>
          {counts.map((part) => (
            <span key={part.key} className={part.className} style={{ width: `${(part.value / record.drafts) * 100}%` }} />
          ))}
        </div>
      )}

      <div className="space-y-1 text-sm">
        <p className={cn("tabular-nums", !judged && "text-muted-foreground")}>
          {judged
            ? t("ai.autopilot.evidence", { good: record.recent.good, drafts: record.recent.drafts, rate: percent(record.recent.rate) })
            : t("ai.autopilot.progress", { drafts: record.recent.drafts, needed: overview.minDrafts })}
        </p>
        {counts.length > 0 && (
          <ul className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground tabular-nums">
            {counts.map((part) => (
              <li key={part.key} className="inline-flex items-center gap-1.5">
                <span className={cn("size-2 rounded-full", part.className)} aria-hidden />
                {t(`ai.autopilot.counts.${part.key}`, { count: part.value })}
              </li>
            ))}
          </ul>
        )}
        {aside.length > 0 && <p className="text-xs text-muted-foreground tabular-nums">{aside.join(" · ")}</p>}
        {record.languages.length > 1 && (
          <p className="text-xs text-muted-foreground tabular-nums">
            {record.languages.map((l) => `${languageName(l.language, locale)} ${l.good}/${l.drafts}`).join(" · ")}
          </p>
        )}
      </div>

      {stage === "paused" && topic.pausedAt && (
        <p className="text-sm text-amber-800 dark:text-amber-300">
          {topic.pauseReason === "flagged"
            ? t("ai.autopilot.pausedFlagged", { when: formatWhen(topic.pausedAt, locale) })
            : t("ai.autopilot.pausedQuality", { when: formatWhen(topic.pausedAt, locale), rate: percent(overview.minRate) })}
        </p>
      )}

      {stage === "on" && topic.mode && (
        <fieldset className="flex flex-wrap gap-x-4 gap-y-1 text-sm" disabled={busy}>
          <legend className="sr-only">{t("ai.autopilot.modeLabel", { topic: topic.topic })}</legend>
          {(["hold", "immediate"] as const).map((mode) => (
            <label key={mode} className="inline-flex items-center gap-1.5">
              <input type="radio" className="accent-primary" name={`support-autopilot-mode-${topic.topic}`} checked={topic.mode === mode} onChange={() => onDecide({ on: true, mode })} />
              {t(`ai.autopilot.mode.${mode}`)}
            </label>
          ))}
        </fieldset>
      )}

      {(onRead || (stage !== "collecting" && topic.enabledBy && topic.enabledAt)) && (
        <p className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
          {onRead && record.drafts > 0 && (
            <button type="button" onClick={onRead} className="underline underline-offset-2 hover:text-foreground">
              {t("ai.autopilot.examples")}
            </button>
          )}
          {stage !== "collecting" && stage !== "eligible" && topic.enabledBy && topic.enabledAt && (
            <span>{t("ai.autopilot.enabledBy", { name: topic.enabledBy.name, when: formatWhen(topic.enabledAt, locale) })}</span>
          )}
        </p>
      )}
      {error && <p className="text-sm text-destructive">{error}</p>}
    </li>
  );
}

/** The bar a topic has to clear, and the only way a team can move it: up. */
function Bar({ overview }: { overview: AutopilotOverview }) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);
  const [drafts, setDrafts] = useState(String(overview.minDrafts));
  const [rate, setRate] = useState(String(percent(overview.minRate)));
  const floor = { drafts: overview.floor.minDrafts, rate: percent(overview.floor.minRate) };
  const save = useMutation({
    mutationFn: () =>
      client.ai!.setAutopilot!({
        // The code's own minimum is stored as "no override", so raising it in code later still takes effect.
        minDrafts: Number(drafts) > floor.drafts ? Number(drafts) : null,
        minRate: Number(rate) > floor.rate ? Number(rate) / 100 : null,
      }),
    onSuccess: () => setOpen(false),
    onSettled: () => queryClient.invalidateQueries({ queryKey: ["support", "ai", "autopilot"] }),
  });
  const valid = Number.isInteger(Number(drafts)) && Number(drafts) >= floor.drafts && Number(rate) >= floor.rate && Number(rate) <= 100;

  return (
    <div className="space-y-2 text-sm text-muted-foreground">
      <p>
        {t("ai.autopilot.rule", { drafts: overview.minDrafts, days: overview.windowDays, rate: percent(overview.minRate) })}{" "}
        {client.ai?.setAutopilot && !open && (
          <button type="button" onClick={() => setOpen(true)} className="underline underline-offset-2 hover:text-foreground">
            {t("ai.autopilot.raise")}
          </button>
        )}
      </p>
      {open && (
        <form
          className="space-y-2 rounded-xl border bg-card p-3"
          onSubmit={(e) => {
            e.preventDefault();
            if (valid) save.mutate();
          }}
        >
          <div className="flex flex-wrap items-end gap-3">
            <label className="grid gap-1 text-xs">
              {t("ai.autopilot.minDrafts")}
              <Input type="number" inputMode="numeric" min={floor.drafts} max={1000} value={drafts} onChange={(e) => setDrafts(e.target.value)} className="h-8 w-24 text-foreground" />
            </label>
            <label className="grid gap-1 text-xs">
              {t("ai.autopilot.minRate")}
              <Input type="number" inputMode="numeric" min={floor.rate} max={100} value={rate} onChange={(e) => setRate(e.target.value)} className="h-8 w-24 text-foreground" />
            </label>
            <Button type="submit" size="sm" disabled={!valid || save.isPending}>
              {save.isPending && <Loader2 className="size-4 animate-spin" />}
              {t("ai.settings.save")}
            </Button>
            <Button type="button" size="sm" variant="ghost" onClick={() => setOpen(false)}>
              {t("actions.cancel")}
            </Button>
          </div>
          <p className="text-xs">{t("ai.autopilot.floor", { drafts: floor.drafts, rate: floor.rate })}</p>
          {save.error && <p className="text-xs text-destructive">{message(save.error, t("ai.failed"))}</p>}
        </form>
      )}
    </div>
  );
}

/** Switching on is a decision with a name on it: the evidence once more, and how replies will go out. */
function SwitchOnDialog({ topic, holdMinutes, onClose, onConfirm }: { topic: AutopilotTopic; holdMinutes: number; onClose: () => void; onConfirm: (mode: AutopilotMode) => void }) {
  const { t } = useSupport();
  const [mode, setMode] = useState<AutopilotMode>("hold");
  return (
    <Dialog open onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{t("ai.autopilot.switchOnTitle", { topic: topic.topic })}</DialogTitle>
          <DialogDescription>{t("ai.autopilot.switchOnDescription")}</DialogDescription>
        </DialogHeader>
        <p className="text-sm tabular-nums">
          {t("ai.autopilot.evidence", { good: topic.record.recent.good, drafts: topic.record.recent.drafts, rate: percent(topic.record.recent.rate) })}
        </p>
        <fieldset className="grid gap-2">
          <legend className="sr-only">{t("ai.autopilot.modeLabel", { topic: topic.topic })}</legend>
          {(["hold", "immediate"] as const).map((option) => (
            <label key={option} className={cn("flex cursor-pointer items-start gap-3 rounded-lg border p-3", mode === option && "border-primary bg-primary/[0.03]")}>
              <input type="radio" name="support-autopilot-mode" className="mt-1 accent-primary" checked={mode === option} onChange={() => setMode(option)} />
              <span className="space-y-0.5">
                <span className="block text-sm font-medium">{t(`ai.autopilot.mode.${option}`)}</span>
                <span className="block text-sm text-muted-foreground">{t(`ai.autopilot.modeHelp.${option}`, { minutes: holdMinutes })}</span>
              </span>
            </label>
          ))}
        </fieldset>
        <DialogFooter>
          <Button type="button" variant="outline" onClick={onClose}>
            {t("actions.cancel")}
          </Button>
          <Button type="button" onClick={() => onConfirm(mode)}>
            {t("ai.autopilot.switchOn")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

const outcomeStyles: Record<AutopilotExample["outcome"], string> = {
  used: "text-foreground",
  light: "text-foreground",
  heavy: "text-amber-700 dark:text-amber-300",
  discarded: "text-muted-foreground",
  flagged: "text-destructive",
  unhappy: "text-destructive",
};

/** The drafts behind a topic's numbers: what was drafted, what went out instead, and the ticket. */
function ExamplesDialog({ topic, onClose }: { topic: string; onClose: () => void }) {
  const { client, t, locale, ticketHref } = useSupport();
  const [onlyChanged, setOnlyChanged] = useState(false);
  const examples = useQuery({
    queryKey: ["support", "ai", "autopilot", "examples", topic, onlyChanged],
    queryFn: () => client.ai!.autopilotExamples!({ topic, ...(onlyChanged ? { only: "changed" as const } : {}) }),
  });
  return (
    <Dialog open onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>{t("ai.autopilot.examplesTitle", { topic })}</DialogTitle>
          <DialogDescription>{t("ai.autopilot.examplesDescription")}</DialogDescription>
        </DialogHeader>
        <label className="inline-flex items-center gap-2 text-sm">
          <input type="checkbox" className="accent-primary" checked={onlyChanged} onChange={(e) => setOnlyChanged(e.target.checked)} />
          {t("ai.autopilot.onlyChanged")}
        </label>
        <div className="max-h-[60vh] space-y-3 overflow-y-auto">
          {examples.error ? (
            <p className="text-sm text-destructive">{t("errors.load")}</p>
          ) : !examples.data ? (
            <Skeleton className="h-40" />
          ) : examples.data.length ? (
            examples.data.map((example) => (
              <article key={example.suggestionId} className="space-y-2 rounded-xl border p-3">
                <header className="flex flex-wrap items-center gap-x-2 gap-y-1 text-xs text-muted-foreground">
                  <span className={cn("font-medium", outcomeStyles[example.outcome])}>{t(`ai.autopilot.outcome.${example.outcome}`)}</span>
                  {example.byAutopilot && <span>{t("ai.autopilot.name")}</span>}
                  <Link href={ticketHref(example.ticket.id)} className="text-foreground underline-offset-2 hover:underline tabular-nums" title={example.ticket.subject ?? undefined}>
                    #{example.ticket.number}
                  </Link>
                  <time className="ms-auto tabular-nums">{formatWhen(example.at, locale)}</time>
                </header>
                <MessageText text={example.draft} className="text-sm" />
                {example.sent && (
                  <div className="space-y-1 border-t pt-2">
                    <p className="text-xs text-muted-foreground">{t("ai.autopilot.sentInstead")}</p>
                    <MessageText text={example.sent} className="text-sm" />
                  </div>
                )}
              </article>
            ))
          ) : (
            <p className="py-6 text-center text-sm text-muted-foreground">{t("ai.autopilot.noExamples")}</p>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

/** The event that says Autopilot sent this message, when it did, and the flag raised on it since. */
export function autopilotMark(detail: TicketDetail, message: TimelineMessage) {
  if (message.kind !== "outbound" || message.authorId) return null;
  const events = detail.timeline.flatMap((entry) => (entry.type === "event" ? [entry.event] : []));
  const sent = events.find((event) => event.type === "autopilot_sent" && event.data.messageId === message.id);
  if (!sent) return null;
  return { sent, flagged: events.find((event) => event.type === "autopilot_flagged" && event.data.messageId === message.id) ?? null };
}

/** Under a reply Autopilot sent, for agents only: that it did, for which topic, and one click to say it was wrong. */
export function AutopilotMark({ detail, sent, flagged, agentName }: { detail: TicketDetail; sent: TimelineEvent; flagged: TimelineEvent | null; agentName: (id: string | null) => string | null }) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  // One click flags. The note is for those who want to say what was wrong, and stays out of the way.
  const [noting, setNoting] = useState(false);
  const [note, setNote] = useState("");
  const flag = useMutation({
    mutationFn: () => client.ai!.flagAutopilotReply!({ suggestionId: String(sent.data.suggestionId), ...(note.trim() ? { note: note.trim() } : {}) }),
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["support", "ticket", detail.ticket.id] });
      queryClient.invalidateQueries({ queryKey: ["support", "tickets"] });
      queryClient.invalidateQueries({ queryKey: ["support", "counts"] });
      queryClient.invalidateQueries({ queryKey: ["support", "ai", "autopilot"] });
    },
  });
  const topic = typeof sent.data.topic === "string" ? sent.data.topic : "";
  return (
    <span className="inline-flex flex-wrap items-center gap-x-3 gap-y-1">
      <span className="inline-flex items-center gap-1.5 text-muted-foreground">
        <Send className="size-3.5" />
        <bdi>{t("ai.autopilot.sentBy", { topic })}</bdi>
      </span>
      {flagged ? (
        <span className="inline-flex items-center gap-1.5 text-destructive">
          <Flag className="size-3.5" />
          {t("ai.autopilot.flaggedBy", { actor: agentName(flagged.actorId) ?? t("ticket.formerAgent") })}
          {typeof flagged.data.note === "string" && flagged.data.note && <bdi className="text-muted-foreground">{flagged.data.note}</bdi>}
        </span>
      ) : (
        client.ai?.flagAutopilotReply && (
          <>
            <button
              type="button"
              className="inline-flex items-center gap-1.5 text-muted-foreground underline underline-offset-2 hover:text-destructive disabled:opacity-60"
              disabled={flag.isPending}
              onClick={() => flag.mutate()}
            >
              {t("ai.autopilot.flag")}
            </button>
            {noting ? (
              <Input
                autoFocus
                dir="auto"
                value={note}
                maxLength={300}
                onChange={(e) => setNote(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !flag.isPending) flag.mutate();
                  if (e.key === "Escape") setNoting(false);
                }}
                placeholder={t("ai.autopilot.flagNotePlaceholder")}
                aria-label={t("ai.autopilot.flagNote")}
                className="h-7 w-56 max-w-full text-xs"
              />
            ) : (
              <button type="button" className="text-muted-foreground underline-offset-2 hover:text-foreground hover:underline" onClick={() => setNoting(true)}>
                {t("ai.autopilot.flagNote")}
              </button>
            )}
          </>
        )
      )}
      {flag.error && <span className="text-destructive">{message(flag.error, t("ai.failed"))}</span>}
    </span>
  );
}

/** A reply waiting out its delay: the text that will go, when, and the way to stop it. */
export function HeldReply({ ticketId, suggestion }: { ticketId: string; suggestion: Suggestion }) {
  const { client, t, locale } = useSupport();
  const queryClient = useQueryClient();
  const stop = useMutation({
    mutationFn: () => client.ai!.holdAutopilotReply!({ suggestionId: suggestion.id }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: ["support", "ticket", ticketId] }),
  });
  return (
    <div className="mx-4 mt-3 space-y-2 rounded-lg border border-primary/25 bg-primary/[0.03] p-3">
      <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2 text-xs">
        <span className="inline-flex items-center gap-1.5 text-muted-foreground">
          <Send className="size-3.5 text-primary" />
          {t("ai.autopilot.held", { time: suggestion.sendAt ? formatWhen(suggestion.sendAt, locale) : "" })}
        </span>
        {client.ai?.holdAutopilotReply && (
          <Button type="button" size="sm" variant="outline" className="h-7" disabled={stop.isPending} onClick={() => stop.mutate()}>
            {stop.isPending && <Loader2 className="size-3.5 animate-spin" />}
            {t("ai.autopilot.stopHeld")}
          </Button>
        )}
      </div>
      <MessageText text={suggestion.text ?? ""} className="text-sm" />
      <SuggestionSources suggestion={suggestion} />
      {stop.error && <p className="text-xs text-destructive">{message(stop.error, t("ai.failed"))}</p>}
    </div>
  );
}

/** Why a reply on a switched-on topic was left to the agent, in one line. Null when there's nothing to say. */
export function useAutopilotReason(suggestion: Suggestion | null) {
  const { t } = useSupport();
  // The agent who stopped a held reply knows why it's theirs.
  if (!suggestion?.autopilotBlock || suggestion.autopilotBlock === "held_back") return null;
  const key = `ai.autopilot.block.${suggestion.autopilotBlock}`;
  const reason = t(key);
  return reason === key ? null : t("ai.autopilot.left", { reason });
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Check, Loader2, Pencil, Plus, RefreshCw, Sparkles, Trash2, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { useSupport } from "./provider";
import type { ActionSetting, ApprovedAnswer, Gap, GuidanceSuggestion } from "./client";
import { formatWhen } from "./format";
import { languageName } from "./ai";
import { ApprovedAnswerDialog, ArticleDialog } from "./memory";
import { AutopilotSettings } from "./autopilot";

type Form = { guidance: string; topics: string[]; draftOnArrival: boolean };

/**
 * Where a team tells AI how they answer: guidance, topics, whether to suggest replies, and what it
 * knows. With memory, also what it learned from them: rules their edits suggest, the answers they
 * approved, and the questions that went unanswered. With Autopilot, which topics it answers alone.
 */
export function SupportAiSettings() {
  const { client, t, locale } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const settings = useQuery({ queryKey: ["support", "ai", "settings"], queryFn: () => ai!.getSettings(), enabled: Boolean(ai) });
  const [form, setForm] = useState<Form | null>(null);
  const [topic, setTopic] = useState("");

  const saved = settings.data;
  useEffect(() => {
    if (saved) setForm((current) => current ?? { guidance: saved.guidance, topics: saved.topics, draftOnArrival: saved.draftOnArrival });
  }, [saved]);

  const save = useMutation({
    mutationFn: (input: Form) => ai!.updateSettings(input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["support", "ai", "settings"] }),
  });
  const sync = useMutation({
    mutationFn: () => ai!.syncKnowledge(),
    onSettled: () => queryClient.invalidateQueries({ queryKey: ["support", "ai", "settings"] }),
  });

  if (!ai) return null;
  if (settings.error) {
    return (
      <div className="rounded-xl border bg-card px-4 py-12 text-center">
        <p className="text-sm text-destructive">{t("errors.load")}</p>
        <Button variant="outline" size="sm" className="mt-3" onClick={() => settings.refetch()}>
          {t("actions.retry")}
        </Button>
      </div>
    );
  }
  if (!saved || !form) return <Skeleton className="h-96 max-w-2xl" />;

  const dirty =
    form.guidance.trim() !== saved.guidance.trim() || form.draftOnArrival !== saved.draftOnArrival || form.topics.join("\n") !== saved.topics.join("\n");
  const change = (patch: Partial<Form>) => {
    save.reset();
    setForm({ ...form, ...patch });
  };
  const addTopic = () => {
    const value = topic.trim().replace(/\s+/g, " ");
    if (value && !form.topics.some((existing) => existing.toLowerCase() === value.toLowerCase())) change({ topics: [...form.topics, value] });
    setTopic("");
  };

  return (
    <div className="max-w-2xl space-y-6">
      <section className="space-y-2">
        <label htmlFor="support-ai-guidance" className="text-sm font-medium">
          {t("ai.settings.guidance")}
        </label>
        <p className="text-sm text-muted-foreground">{t("ai.settings.guidanceHelp")}</p>
        <Textarea
          id="support-ai-guidance"
          dir="auto"
          value={form.guidance}
          onChange={(e) => change({ guidance: e.target.value })}
          placeholder={t("ai.settings.guidancePlaceholder")}
          className="min-h-40"
        />
        <GuidanceSuggestions
          onAccepted={(rule) => {
            save.reset();
            // The server added the rule to the saved guidance; the form follows, keeping what's being typed.
            setForm((current) => current && { ...current, guidance: current.guidance.trim() ? `${current.guidance.trim()}\n${rule}` : rule });
            queryClient.invalidateQueries({ queryKey: ["support", "ai", "settings"] });
          }}
        />
      </section>

      <section className="space-y-2">
        <label htmlFor="support-ai-topic" className="text-sm font-medium">
          {t("ai.settings.topics")}
        </label>
        <p className="text-sm text-muted-foreground">{t("ai.settings.topicsHelp")}</p>
        <div className="flex flex-wrap items-center gap-1.5">
          {form.topics.map((name) => (
            <span key={name} className="inline-flex items-center gap-1 rounded-md border bg-background px-2 py-1 text-sm">
              <bdi>{name}</bdi>
              <button
                type="button"
                onClick={() => change({ topics: form.topics.filter((existing) => existing !== name) })}
                className="text-muted-foreground hover:text-foreground"
                aria-label={t("ai.settings.removeTopic", { name })}
              >
                <X className="size-3.5" />
              </button>
            </span>
          ))}
          <Input
            id="support-ai-topic"
            value={topic}
            maxLength={40}
            onChange={(e) => setTopic(e.target.value)}
            onBlur={addTopic}
            onKeyDown={(e) => {
              if (e.key === "Enter" || e.key === ",") {
                e.preventDefault();
                addTopic();
              }
            }}
            placeholder={t("ai.settings.addTopic")}
            className="h-8 w-40"
          />
        </div>
      </section>

      <section className="flex items-start justify-between gap-4">
        <div className="space-y-1">
          <label htmlFor="support-ai-arrival" className="text-sm font-medium">
            {t("ai.settings.draftOnArrival")}
          </label>
          <p className="text-sm text-muted-foreground">{t("ai.settings.draftOnArrivalHelp")}</p>
        </div>
        <Switch id="support-ai-arrival" checked={form.draftOnArrival} onCheckedChange={(checked) => change({ draftOnArrival: Boolean(checked) })} />
      </section>

      <div className="flex items-center gap-3">
        <Button type="button" disabled={!dirty || save.isPending} onClick={() => save.mutate({ ...form, guidance: form.guidance.trim() })}>
          {save.isPending && <Loader2 className="size-4 animate-spin" />}
          {t("ai.settings.save")}
        </Button>
        {save.isSuccess && !dirty && (
          <span className="inline-flex items-center gap-1 text-sm text-muted-foreground">
            <Check className="size-4" />
            {t("ai.settings.saved")}
          </span>
        )}
        {save.error && <span className="text-sm text-destructive">{save.error instanceof Error && save.error.message ? save.error.message : t("errors.send")}</span>}
      </div>

      <section className="space-y-2 border-t pt-6">
        <div className="flex items-start justify-between gap-4">
          <div className="space-y-1">
            <h2 className="text-sm font-medium">{t("ai.settings.knowledge")}</h2>
            <p className="text-sm text-muted-foreground">{t("ai.settings.knowledgeHelp")}</p>
          </div>
          {saved.sources.length > 0 && (
            <Button type="button" variant="outline" size="sm" disabled={sync.isPending} onClick={() => sync.mutate()}>
              {sync.isPending ? <Loader2 className="size-4 animate-spin" /> : <RefreshCw className="size-4" />}
              {t("ai.settings.sync")}
            </Button>
          )}
        </div>
        {saved.sources.length ? (
          <ul className="divide-y rounded-xl border bg-card">
            {saved.sources.map((source) => (
              <li key={source.id} className="flex flex-wrap items-center justify-between gap-x-4 gap-y-1 px-4 py-3 text-sm">
                <bdi className="font-medium">{source.id}</bdi>
                <span className="text-muted-foreground tabular-nums">
                  {t("ai.settings.articles", { count: source.articles })}
                  {" · "}
                  {source.syncedAt ? t("ai.settings.synced", { when: formatWhen(source.syncedAt, locale) }) : t("ai.settings.neverSynced")}
                </span>
              </li>
            ))}
          </ul>
        ) : (
          <p className="rounded-xl border border-dashed px-4 py-6 text-center text-sm text-muted-foreground">{t("ai.settings.noSources")}</p>
        )}
        {sync.error && <p className="text-sm text-destructive">{t("ai.failed")}</p>}
      </section>

      <AutopilotSettings />
      <Actions actions={saved.actions ?? []} />
      <ApprovedAnswers />
      <Gaps />
    </div>
  );
}

/**
 * What AI can do in your product, as declared in code. A lookup can be kept from running on its
 * own; whether an action needs approval is not a setting.
 */
function Actions({ actions }: { actions: ActionSetting[] }) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const toggle = useMutation({
    mutationFn: (input: { name: string; enabled: boolean }) => ai!.setActionEnabled!(input),
    onSettled: () => queryClient.invalidateQueries({ queryKey: ["support", "ai", "settings"] }),
  });
  if (!actions.length) return null;

  return (
    <section className="space-y-2 border-t pt-6">
      <div className="space-y-1">
        <h2 className="text-sm font-medium">{t("ai.actions.heading")}</h2>
        <p className="text-sm text-muted-foreground">{t("ai.actions.help")}</p>
      </div>
      <ul className="divide-y rounded-xl border bg-card">
        {actions.map((action) => {
          const lookup = action.approval === "never";
          // While the change is on its way, the switch shows where it's going.
          const enabled = toggle.isPending && toggle.variables?.name === action.name ? toggle.variables.enabled : action.enabled;
          return (
            <li key={action.name} className="flex items-center justify-between gap-4 px-4 py-3">
              <div className="min-w-0">
                {lookup && ai?.setActionEnabled ? (
                  <label htmlFor={`support-action-${action.name}`} className="text-sm font-medium">
                    {action.title}
                  </label>
                ) : (
                  <p className="text-sm font-medium">{action.title}</p>
                )}
                <p className="text-sm text-muted-foreground">{t(!lookup ? "ai.actions.needsApproval" : enabled ? "ai.actions.runsAlone" : "ai.actions.runsByHand")}</p>
              </div>
              {lookup && ai?.setActionEnabled && (
                <Switch
                  id={`support-action-${action.name}`}
                  checked={enabled}
                  disabled={toggle.isPending}
                  onCheckedChange={(checked) => toggle.mutate({ name: action.name, enabled: Boolean(checked) })}
                />
              )}
            </li>
          );
        })}
      </ul>
      {toggle.error && <p className="text-sm text-destructive">{toggle.error instanceof Error && toggle.error.message ? toggle.error.message : t("ai.failed")}</p>}
    </section>
  );
}

const ticketLink = "text-foreground underline-offset-2 hover:underline tabular-nums";

/** Rules the team's own edits suggest, under the guidance they would join. Nothing is added until someone accepts. */
function GuidanceSuggestions({ onAccepted }: { onAccepted: (rule: string) => void }) {
  const { client, t, ticketHref } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const suggestions = useQuery({
    queryKey: ["support", "ai", "guidance-suggestions"],
    queryFn: () => ai!.listGuidanceSuggestions!(),
    enabled: Boolean(ai?.listGuidanceSuggestions && ai.decideGuidanceSuggestion),
  });
  const [rules, setRules] = useState<Record<string, string>>({});
  const decide = useMutation({
    mutationFn: (input: { id: string; accept: boolean; rule?: string }) => ai!.decideGuidanceSuggestion!(input),
    onSuccess: (_, input) => {
      if (input.accept && input.rule) onAccepted(input.rule);
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: ["support", "ai", "guidance-suggestions"] }),
  });
  if (!suggestions.data?.length) return null;

  return (
    <ul className="space-y-2 pt-1">
      {suggestions.data.map((suggestion: GuidanceSuggestion) => {
        const rule = rules[suggestion.id] ?? suggestion.rule;
        const busy = decide.isPending && decide.variables?.id === suggestion.id;
        return (
          <li key={suggestion.id} className="space-y-2 rounded-xl border bg-card p-3">
            <p className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
              <Sparkles className="size-3.5 text-primary" />
              {t("ai.guidanceSuggestions.label")}
            </p>
            <Textarea
              dir="auto"
              value={rule}
              onChange={(e) => setRules({ ...rules, [suggestion.id]: e.target.value })}
              aria-label={t("ai.guidanceSuggestions.rule")}
              className="min-h-0"
              rows={2}
            />
            <p dir="auto" className="text-sm text-muted-foreground">
              {suggestion.reason}
              {suggestion.tickets.length > 0 && (
                <>
                  {" "}
                  {t("ai.guidanceSuggestions.seenIn")}{" "}
                  {suggestion.tickets.map((ticket, index) => (
                    <span key={ticket.id}>
                      {index > 0 && ", "}
                      <Link href={ticketHref(ticket.id)} className={ticketLink}>
                        #{ticket.number}
                      </Link>
                    </span>
                  ))}
                  .
                </>
              )}
            </p>
            <div className="flex items-center gap-2">
              <Button type="button" size="sm" disabled={!rule.trim() || decide.isPending} onClick={() => decide.mutate({ id: suggestion.id, accept: true, rule: rule.trim() })}>
                {busy && <Loader2 className="size-4 animate-spin" />}
                {t("ai.guidanceSuggestions.accept")}
              </Button>
              <Button type="button" size="sm" variant="ghost" disabled={decide.isPending} onClick={() => decide.mutate({ id: suggestion.id, accept: false })}>
                {t("ai.guidanceSuggestions.dismiss")}
              </Button>
              {decide.isError && decide.variables?.id === suggestion.id && (
                <span className="text-sm text-destructive">{decide.error instanceof Error && decide.error.message ? decide.error.message : t("ai.failed")}</span>
              )}
            </div>
          </li>
        );
      })}
    </ul>
  );
}

/** The answers the team approved: listed, changed and removed here; saved from replies on the ticket. */
function ApprovedAnswers() {
  const { client, t, locale } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const enabled = Boolean(ai?.listApprovedAnswers && ai.saveApprovedAnswer);
  const answers = useQuery({ queryKey: ["support", "ai", "answers"], queryFn: () => ai!.listApprovedAnswers!(), enabled });
  const [editing, setEditing] = useState<ApprovedAnswer | "new" | null>(null);
  const [removing, setRemoving] = useState<string | null>(null);
  const remove = useMutation({
    mutationFn: (id: string) => ai!.deleteApprovedAnswer!({ id }),
    onSettled: () => {
      setRemoving(null);
      queryClient.invalidateQueries({ queryKey: ["support", "ai", "answers"] });
    },
  });
  if (!enabled) return null;

  return (
    <section className="space-y-2 border-t pt-6">
      <div className="flex items-start justify-between gap-4">
        <div className="space-y-1">
          <h2 className="text-sm font-medium">{t("ai.answers.heading")}</h2>
          <p className="text-sm text-muted-foreground">{t("ai.answers.help")}</p>
        </div>
        <Button type="button" variant="outline" size="sm" onClick={() => setEditing("new")}>
          <Plus className="size-4" />
          {t("ai.answers.new")}
        </Button>
      </div>
      {answers.data?.length ? (
        <ul className="divide-y rounded-xl border bg-card">
          {answers.data.map((answer) => (
            <li key={answer.id} className="flex items-center gap-3 px-4 py-3">
              <div className="min-w-0 flex-1">
                <p className="flex items-center gap-2 text-sm font-medium">
                  <bdi className="truncate">{answer.title}</bdi>
                  {answer.language && (
                    <span className="shrink-0 rounded-md border px-1.5 py-0.5 text-[11px] font-normal text-muted-foreground">
                      {t("ai.answers.languageOnly", { language: languageName(answer.language, locale) })}
                    </span>
                  )}
                </p>
                <p dir="auto" className="truncate text-sm text-muted-foreground">
                  {answer.text.replace(/\s+/g, " ")}
                </p>
              </div>
              {removing === answer.id ? (
                <span className="flex shrink-0 items-center gap-1">
                  <Button type="button" size="sm" variant="destructive" disabled={remove.isPending} onClick={() => remove.mutate(answer.id)}>
                    {remove.isPending && <Loader2 className="size-4 animate-spin" />}
                    {t("ai.answers.confirmDelete")}
                  </Button>
                  <Button type="button" size="sm" variant="ghost" onClick={() => setRemoving(null)}>
                    {t("actions.cancel")}
                  </Button>
                </span>
              ) : (
                <span className="flex shrink-0 items-center">
                  <Button type="button" size="icon" variant="ghost" className="size-8" onClick={() => setEditing(answer)} aria-label={t("ai.answers.edit", { title: answer.title })}>
                    <Pencil className="size-4" />
                  </Button>
                  {ai?.deleteApprovedAnswer && (
                    <Button type="button" size="icon" variant="ghost" className="size-8" onClick={() => setRemoving(answer.id)} aria-label={t("ai.answers.delete", { title: answer.title })}>
                      <Trash2 className="size-4" />
                    </Button>
                  )}
                </span>
              )}
            </li>
          ))}
        </ul>
      ) : answers.data ? (
        <p className="rounded-xl border border-dashed px-4 py-6 text-center text-sm text-muted-foreground">{t("ai.answers.empty")}</p>
      ) : (
        <Skeleton className="h-16" />
      )}
      <ApprovedAnswerDialog open={editing !== null} onOpenChange={(open) => !open && setEditing(null)} answer={editing && editing !== "new" ? editing : undefined} />
    </section>
  );
}

/** What the knowledge is missing: each gap is closed by writing its answer, drafting an article from the tickets, or dismissing it. */
function Gaps() {
  const { client, t, locale, ticketHref } = useSupport();
  const queryClient = useQueryClient();
  const ai = client.ai;
  const gaps = useQuery({ queryKey: ["support", "ai", "gaps"], queryFn: () => ai!.listGaps!(), enabled: Boolean(ai?.listGaps) });
  const [writing, setWriting] = useState<Gap | null>(null);
  const [drafting, setDrafting] = useState<Gap | null>(null);
  const dismiss = useMutation({
    mutationFn: (id: string) => ai!.dismissGap!({ id }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: ["support", "ai", "gaps"] }),
  });
  if (!ai?.listGaps) return null;

  return (
    <section id="support-gaps" className="scroll-mt-6 space-y-2 border-t pt-6">
      <div className="space-y-1">
        <h2 className="text-sm font-medium">{t("ai.gaps.heading")}</h2>
        <p className="text-sm text-muted-foreground">{t("ai.gaps.help")}</p>
      </div>
      {gaps.data?.length ? (
        <ul className="divide-y rounded-xl border bg-card">
          {gaps.data.map((gap) => (
            <li key={gap.id} className="space-y-2 px-4 py-3">
              <div>
                <p dir="auto" className="text-sm font-medium">
                  {gap.theme}
                </p>
                <p className="text-sm text-muted-foreground">
                  {gap.count === 1 ? t("ai.gaps.askedOnce") : t("ai.gaps.asked", { count: gap.count })}
                  {gap.lastSeenAt && <> · {t("ai.gaps.lastSeen", { when: formatWhen(gap.lastSeenAt, locale) })}</>}
                  {gap.tickets.map((ticket) => (
                    <span key={ticket.id}>
                      {" · "}
                      <Link href={ticketHref(ticket.id)} className={ticketLink} title={ticket.subject ?? undefined}>
                        #{ticket.number}
                      </Link>
                    </span>
                  ))}
                </p>
              </div>
              <div className="flex flex-wrap items-center gap-2">
                {ai.saveApprovedAnswer && (
                  <Button type="button" size="sm" variant="outline" onClick={() => setWriting(gap)}>
                    {t("ai.gaps.write")}
                  </Button>
                )}
                {ai.draftArticle && (
                  <Button type="button" size="sm" variant="outline" onClick={() => setDrafting(gap)}>
                    {t("ai.article.draft")}
                  </Button>
                )}
                {ai.dismissGap && (
                  <Button type="button" size="sm" variant="ghost" disabled={dismiss.isPending} onClick={() => dismiss.mutate(gap.id)}>
                    {t("ai.gaps.dismiss")}
                  </Button>
                )}
              </div>
            </li>
          ))}
        </ul>
      ) : gaps.data ? (
        <p className="rounded-xl border border-dashed px-4 py-6 text-center text-sm text-muted-foreground">{t("ai.gaps.empty")}</p>
      ) : (
        <Skeleton className="h-16" />
      )}
      <ApprovedAnswerDialog open={writing !== null} onOpenChange={(open) => !open && setWriting(null)} gap={writing ?? undefined} />
      {drafting && <ArticleDialog open onOpenChange={(open) => !open && setDrafting(null)} from={{ gapId: drafting.id }} />}
    </section>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Check, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useSupport } from "./provider";
import type { TicketDetail } from "./client";
import { contactLabel } from "./format";

/** Links the sender to one of your customers. Their later messages link on their own. */
export function LinkCustomerDialog({
  detail,
  open,
  onOpenChange,
}: {
  detail: TicketDetail;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  const [query, setQuery] = useState("");
  const [debounced, setDebounced] = useState("");
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(query.trim()), 250);
    return () => clearTimeout(timer);
  }, [query]);

  const results = useQuery({
    queryKey: ["support", "customers", debounced],
    queryFn: () => client.searchCustomers(debounced),
    enabled: open && debounced.length >= 2,
  });
  const link = useMutation({
    mutationFn: (customerId: string | null) => client.linkCustomer({ ticketId: detail.ticket.id, customerId }),
    onSuccess: () => {
      onOpenChange(false);
      setQuery("");
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["support", "ticket", detail.ticket.id] });
      queryClient.invalidateQueries({ queryKey: ["support", "tickets"] });
    },
  });

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{t("link.title")}</DialogTitle>
          <DialogDescription>{t("link.description", { name: contactLabel(detail.contact) })}</DialogDescription>
        </DialogHeader>
        <Input autoFocus value={query} onChange={(e) => setQuery(e.target.value)} placeholder={t("link.search")} aria-label={t("link.search")} />
        <div className="max-h-72 min-h-24 overflow-y-auto">
          {results.isFetching ? (
            <Loader2 className="mx-auto mt-6 size-4 animate-spin text-muted-foreground" />
          ) : debounced.length < 2 ? (
            <p className="pt-6 text-center text-sm text-muted-foreground">{t("link.hint")}</p>
          ) : results.data?.length ? (
            <ul className="divide-y">
              {results.data.map((customer) => (
                <li key={customer.id}>
                  <button
                    type="button"
                    disabled={link.isPending}
                    onClick={() => link.mutate(customer.id)}
                    className="flex w-full items-center justify-between gap-2 px-1 py-2.5 text-start text-sm hover:bg-muted/50"
                  >
                    <bdi className="truncate">{customer.name}</bdi>
                    {customer.id === detail.customer?.id && <Check className="size-4 text-primary" />}
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <p className="pt-6 text-center text-sm text-muted-foreground">{t("link.none")}</p>
          )}
        </div>
        {detail.customer && (
          <Button variant="ghost" size="sm" className="justify-self-start" disabled={link.isPending} onClick={() => link.mutate(null)}>
            {t("link.unlink", { name: detail.customer.name })}
          </Button>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useSupport } from "./provider";
import type { TicketDetail } from "./client";

/** Makes someone else the ticket's contact, such as the customer when a teammate's email opened it. */
export function ChangeContactDialog({
  detail,
  open,
  onOpenChange,
}: {
  detail: TicketDetail;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const { client, t } = useSupport();
  const queryClient = useQueryClient();
  const [address, setAddress] = useState("");
  const change = useMutation({
    mutationFn: () => client.changeContact({ ticketId: detail.ticket.id, address: address.trim() }),
    onSuccess: () => {
      onOpenChange(false);
      setAddress("");
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["support", "ticket", detail.ticket.id] });
      queryClient.invalidateQueries({ queryKey: ["support", "tickets"] });
    },
  });

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) change.reset();
        onOpenChange(next);
      }}
    >
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{t("contact.title")}</DialogTitle>
          <DialogDescription>{t("contact.description")}</DialogDescription>
        </DialogHeader>
        <form
          className="grid gap-4"
          onSubmit={(e) => {
            e.preventDefault();
            if (address.trim()) change.mutate();
          }}
        >
          <Input
            autoFocus
            type="email"
            dir="ltr"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
            placeholder={t("composer.ccPlaceholder")}
            aria-label={t("contact.email")}
          />
          {change.error && (
            <p className="text-sm text-destructive">{change.error instanceof Error && change.error.message ? change.error.message : t("errors.send")}</p>
          )}
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              {t("actions.cancel")}
            </Button>
            <Button type="submit" disabled={!address.trim() || change.isPending}>
              {change.isPending && <Loader2 className="size-4 animate-spin" />}
              {t("contact.save")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ArrowLeft, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { usePortal } from "./provider";
import type { PortalTicket, TicketStatus } from "./client";
import { formatTimestamp, formatWhen } from "./format";
import { AttachmentChip, MessageText } from "./parts";

/** A customer's own requests, inside your app. Conversations also continue by email. */
export function SupportRequests({ newRequestOpen, onNewRequestOpenChange }: { newRequestOpen: boolean; onNewRequestOpenChange: (open: boolean) => void }) {
  const { client, t } = usePortal();
  const list = useQuery({ queryKey: ["support-portal", "list"], queryFn: () => client.list(), refetchInterval: 30_000 });

  return (
    <>
      {list.error ? (
        <div className="rounded-xl border bg-card px-4 py-12 text-center">
          <p className="text-sm text-destructive">{t("errors.load")}</p>
          <Button variant="outline" size="sm" className="mt-3" onClick={() => list.refetch()}>
            {t("actions.retry")}
          </Button>
        </div>
      ) : list.isPending ? (
        <div className="space-y-2">
          {Array.from({ length: 3 }, (_, i) => (
            <Skeleton key={i} className="h-16" />
          ))}
        </div>
      ) : list.data.items.length ? (
        <ul className="divide-y overflow-hidden rounded-xl border bg-card">
          {list.data.items.map((item) => (
            <RequestRow key={item.id} item={item} />
          ))}
        </ul>
      ) : (
        <div className="rounded-xl border border-dashed px-6 py-14 text-center">
          <p className="text-sm font-medium">{t("portal.emptyTitle")}</p>
          <p className="mt-1 text-sm text-muted-foreground">{t("portal.emptyBody")}</p>
          <Button className="mt-4" size="sm" onClick={() => onNewRequestOpenChange(true)}>
            {t("portal.newRequest")}
          </Button>
        </div>
      )}
      <NewRequestDialog open={newRequestOpen} onOpenChange={onNewRequestOpenChange} />
    </>
  );
}

/** The customer's view of a status: whose turn it is. */
const portalStatus = (status: TicketStatus) => (status === "waiting" ? "awaitingYou" : status === "solved" ? "solved" : "open");

const portalStatusStyles = {
  open: "bg-blue-50 text-blue-700 ring-blue-600/20 dark:bg-blue-500/10 dark:text-blue-300",
  awaitingYou: "bg-amber-50 text-amber-800 ring-amber-600/20 dark:bg-amber-500/10 dark:text-amber-300",
  solved: "bg-emerald-50 text-emerald-700 ring-emerald-600/20 dark:bg-emerald-500/10 dark:text-emerald-300",
};

function PortalStatus({ status }: { status: TicketStatus }) {
  const { t } = usePortal();
  const key = portalStatus(status);
  return (
    <span className={cn("inline-flex shrink-0 items-center rounded-md px-1.5 py-0.5 text-xs font-medium ring-1 ring-inset", portalStatusStyles[key])}>
      {t(`portal.status.${key}`)}
    </span>
  );
}

function RequestRow({ item }: { item: PortalTicket }) {
  const { t, locale, requestHref } = usePortal();
  return (
    <li>
      <Link href={requestHref(item.id)} className="flex items-center gap-4 px-4 py-3.5 transition-colors hover:bg-muted/50">
        <span className={cn("size-2 shrink-0 rounded-full", item.unread ? "bg-primary" : "bg-transparent")} aria-label={item.unread ? t("portal.newReply") : undefined} />
        <div className="min-w-0 flex-1">
          <p dir="auto" className={cn("truncate text-sm", item.unread ? "font-semibold" : "font-medium")}>
            {item.subject || t("inbox.noSubject")}
          </p>
          {item.preview && (
            <p dir="auto" className="truncate text-sm text-muted-foreground">
              {item.previewKind === "outbound" && item.previewAuthor && <bdi className="text-foreground/70">{item.previewAuthor}: </bdi>}
              {item.preview}
            </p>
          )}
        </div>
        <PortalStatus status={item.status} />
        <span className="w-14 shrink-0 text-end text-xs text-muted-foreground tabular-nums">{formatWhen(item.lastMessageAt, locale)}</span>
      </Link>
    </li>
  );
}

function NewRequestDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (open: boolean) => void }) {
  const { client, t, requestHref } = usePortal();
  const router = useRouter();
  const queryClient = useQueryClient();
  const [subject, setSubject] = useState("");
  const [text, setText] = useState("");
  const create = useMutation({
    mutationFn: () => client.create({ subject, text }),
    onSuccess: ({ id }) => {
      queryClient.invalidateQueries({ queryKey: ["support-portal"] });
      onOpenChange(false);
      setSubject("");
      setText("");
      router.push(requestHref(id));
    },
  });
  const ready = subject.trim() && text.trim() && !create.isPending;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>{t("portal.newRequest")}</DialogTitle>
        </DialogHeader>
        <form
          className="space-y-3"
          onSubmit={(e) => {
            e.preventDefault();
            if (ready) create.mutate();
          }}
        >
          <label className="block space-y-1.5">
            <span className="text-sm font-medium">{t("portal.subject")}</span>
            <Input value={subject} dir="auto" maxLength={200} onChange={(e) => setSubject(e.target.value)} autoFocus />
          </label>
          <label className="block space-y-1.5">
            <span className="text-sm font-medium">{t("portal.message")}</span>
            <Textarea value={text} dir="auto" maxLength={10_000} onChange={(e) => setText(e.target.value)} className="min-h-36" />
          </label>
          {create.error && <p className="text-sm text-destructive">{t("errors.send")}</p>}
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              {t("actions.cancel")}
            </Button>
            <Button type="submit" disabled={!ready}>
              {create.isPending && <Loader2 className="size-4 animate-spin" />}
              {t("portal.send")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/** One request: the conversation and a reply box. */
export function SupportRequest({ id }: { id: string }) {
  const { client, t, locale, listHref } = usePortal();
  const queryClient = useQueryClient();
  const [text, setText] = useState("");
  const request = useQuery({ queryKey: ["support-portal", "request", id], queryFn: () => client.get(id), refetchInterval: 20_000 });
  const reply = useMutation({
    mutationFn: () => client.reply({ ticketId: id, text }),
    onSuccess: () => setText(""),
    onSettled: () => queryClient.invalidateQueries({ queryKey: ["support-portal"] }),
  });

  if (request.error) {
    return <p className="rounded-xl border bg-card px-4 py-12 text-center text-sm text-muted-foreground">{t("portal.notFound")}</p>;
  }
  if (!request.data) return <Skeleton className="h-96" />;
  const { ticket, messages } = request.data;

  return (
    <div className="mx-auto max-w-3xl space-y-5">
      <div>
        <Link href={listHref} className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">
          <ArrowLeft className="size-4 rtl:rotate-180" />
          {t("portal.back")}
        </Link>
        <div className="mt-1 flex flex-wrap items-center gap-3">
          <h1 dir="auto" className="text-2xl font-semibold tracking-tight break-words">
            {ticket.subject || t("inbox.noSubject")}
          </h1>
          <PortalStatus status={ticket.status} />
        </div>
      </div>

      <ol className="space-y-3">
        {messages.map((message) => (
          <li key={message.id}>
            <article className={cn("rounded-xl border p-4", message.kind === "outbound" ? "border-primary/20 bg-primary/[0.03]" : "bg-card")}>
              <header className="mb-2 flex items-center gap-2 text-xs text-muted-foreground">
                <bdi className="text-sm font-medium text-foreground">
                  {message.kind === "inbound" ? message.author ?? t("portal.you") : message.author ?? t("portal.team")}
                </bdi>
                <time className="ms-auto tabular-nums">{formatTimestamp(message.createdAt, locale)}</time>
              </header>
              <MessageText text={message.text} />
              {message.attachments.length > 0 && (
                <div className="mt-3 flex flex-wrap gap-2">
                  {message.attachments.map((file) => (
                    <AttachmentChip key={file.id} file={file} locale={locale} getUrl={() => client.attachmentUrl({ id: file.id })} />
                  ))}
                </div>
              )}
            </article>
          </li>
        ))}
      </ol>

      <form
        className="rounded-xl border bg-card"
        onSubmit={(e) => {
          e.preventDefault();
          if (text.trim() && !reply.isPending) reply.mutate();
        }}
      >
        <Textarea
          value={text}
          dir="auto"
          onChange={(e) => setText(e.target.value)}
          placeholder={t("portal.replyPlaceholder")}
          aria-label={t("portal.replyPlaceholder")}
          className="min-h-28 resize-y border-0 bg-transparent px-4 shadow-none focus-visible:ring-0 dark:bg-transparent"
        />
        <div className="flex items-center justify-between gap-2 border-t px-3 py-2">
          <p className="text-xs text-muted-foreground">{reply.error ? <span className="text-destructive">{t("errors.send")}</span> : t("portal.emailNote")}</p>
          <Button type="submit" size="sm" disabled={!text.trim() || reply.isPending}>
            {reply.isPending && <Loader2 className="size-4 animate-spin" />}
            {t("portal.send")}
          </Button>
        </div>
      </form>
    </div>
  );
}
